using System.Text.Json.Serialization;

namespace CodeIndex;

public class TypeRec
{
    public string Id { get; set; }            // full name: Ns.Outer.Inner
    public string Name { get; set; }          // simple name, no generics
    public string Kind { get; set; }          // class|struct|interface|enum|record|delegate
    public string File { get; set; }          // path relative to src root, '/'
    public int LineStart { get; set; }
    public int LineEnd { get; set; }
    public string Namespace { get; set; }
    public string Base { get; set; }          // as written, e.g. State<Player>
    public string BaseName { get; set; }      // simple name without generics/qualifier
    public string BaseResolved { get; set; }  // resolved type Id if unique/likely
    public List<string> Interfaces { get; set; } = new();
    public string Parent { get; set; }        // nesting parent Id
    public List<string> Modifiers { get; set; } = new();
    public List<string> Attributes { get; set; } = new();
    public List<string> Generics { get; set; }
    public string Signature { get; set; }     // delegates
    public List<EnumMemberRec> Members { get; set; } // enums only

    [JsonIgnore] public int Pos; // SpanStart for phase-2 matching
    [JsonIgnore] public int FileIdx;
    [JsonIgnore] public List<string> BaseArgs = new();
}

public class EnumMemberRec
{
    public string Name { get; set; }
    public string Value { get; set; }   // computed decimal string when derivable
    public string Raw { get; set; }     // explicit expression text, if any
    public int Line { get; set; }
}

public class FieldRec
{
    public string Owner { get; set; }
    public string Name { get; set; }
    public string Kind { get; set; }          // field|property|event
    public string Type { get; set; }
    public bool Static { get; set; }
    public bool Const { get; set; }
    public bool Readonly { get; set; }
    public List<string> Modifiers { get; set; } = new();
    public string Initializer { get; set; }   // literal value (normalized) if initializer is a literal
    public string InitExpr { get; set; }      // initializer text <=120
    public string File { get; set; }
    public int Line { get; set; }
    public List<string> Attributes { get; set; }
}

public class CallRec
{
    public string Name { get; set; }          // callee name; ".ctor" for new T(...)
    public string Receiver { get; set; }      // receiver expression text (<=60), null for implicit this
    public string ReceiverType { get; set; }  // resolved simple type name (heuristic), null if unknown
    public int Line { get; set; }
    public int Count { get; set; } = 1;
    [JsonIgnore] public SyntaxNodeHolder Holder;
}

public class SyntaxNodeHolder { }

public class MethodRec
{
    public string Owner { get; set; }
    public string Name { get; set; }          // method name; ".ctor"; "Prop.get"
    public string Kind { get; set; }          // method|ctor|dtor|operator|accessor|conversion
    public string Signature { get; set; }
    public List<string> Modifiers { get; set; } = new();
    public string File { get; set; }
    public int LineStart { get; set; }
    public int LineEnd { get; set; }
    public bool Override { get; set; }
    public string OverrideOf { get; set; }    // Base.Method when resolvable
    public List<CallRec> Calls { get; set; } = new();
    public List<string> Attributes { get; set; }

    [JsonIgnore] public int Pos;
    [JsonIgnore] public int FileIdx;
    [JsonIgnore] public string ReturnType;
    [JsonIgnore] public int ParamCount;
}

public class LiteralRec
{
    public string Kind { get; set; }          // num|str
    public string Value { get; set; }         // num: invariant decimal string of numeric value; str: text (<=200)
    public string Text { get; set; }          // num: raw token text incl. suffix
    public string OwnerType { get; set; }
    public string Owner { get; set; }         // member name
    public string OwnerKind { get; set; }     // method|field|property|enum|attribute|type
    public string File { get; set; }
    public int Line { get; set; }
    public string Expr { get; set; }          // <=120
    public string Context { get; set; }       // e.g. Lerp(0.5f, ...) | target = | return | cmp: x >
}

