using System.Text;
using System.Text.RegularExpressions;

namespace CodeIndex;

/// <summary>Global symbol tables built after phase 1 and used by phase 2 for syntactic type resolution.</summary>
public class Db
{
    public List<string> Files = new();
    public List<TypeRec> Types = new();
    public List<FieldRec> Fields = new();
    public List<MethodRec> Methods = new();
    public Dictionary<(int, int), TypeRec> TypeByPos = new();
    public Dictionary<(int, int), MethodRec> MethodByPos = new();

    public Dictionary<string, List<TypeRec>> ByName = new();
    public Dictionary<string, TypeRec> Canon = new();
    public Dictionary<string, Dictionary<string, string>> FieldTypes = new();
    public Dictionary<string, Dictionary<string, string>> MethodRet = new();
    public Dictionary<string, HashSet<string>> MethodNames = new();

    static readonly HashSet<string> Collections = new() { "List", "IList", "IEnumerable", "HashSet", "Queue", "Stack", "Array", "ICollection", "IReadOnlyList", "LinkedList", "SortedSet" };

    // ---------- type text helpers ----------
    public static string Head(string t)
    {
        if (string.IsNullOrEmpty(t)) return null;
        t = t.Trim();
        while (t.EndsWith("?") || t.EndsWith("]")) { t = t.EndsWith("?") ? t[..^1] : (t.LastIndexOf('[') >= 0 ? t[..t.LastIndexOf('[')] : t[..^1]); }
        int lt = t.IndexOf('<');
        if (lt >= 0) t = t[..lt];
        int dot = t.LastIndexOf('.');
        if (dot >= 0) t = t[(dot + 1)..];
        t = t.Trim();
        return t.Length == 0 || t == "var" ? null : t;
    }

    public static List<string> Args(string t)
    {
        var res = new List<string>();
        if (t == null) return res;
        int lt = t.IndexOf('<'); int gt = t.LastIndexOf('>');
        if (lt < 0 || gt <= lt) return res;
        int depth = 0; var sb = new StringBuilder();
        for (int i = lt + 1; i < gt; i++)
        {
            char c = t[i];
            if (c == '<') depth++; else if (c == '>') depth--;
            if (c == ',' && depth == 0) { res.Add(sb.ToString().Trim()); sb.Clear(); } else sb.Append(c);
        }
        if (sb.Length > 0) res.Add(sb.ToString().Trim());
        return res;
    }

    public static string ElemType(string t)
    {
        if (t == null) return null;
        t = t.Trim();
        if (t.EndsWith("[]")) return t[..^2];
        var h = Head(t);
        var a = Args(t);
        if (a.Count == 0) return null;
        if (h == "Dictionary" || h == "IDictionary" || h == "SortedDictionary") return a.Count >= 2 ? a[1] : null;
        if (Collections.Contains(h)) return a[0];
        return null;
    }

    static string Subst(string t, List<string> gens, List<string> args)
    {
        if (t == null || gens == null || gens.Count == 0 || args == null || args.Count != gens.Count) return t;
        for (int i = 0; i < gens.Count; i++)
        {
            if (t == gens[i]) return args[i];
        }
        foreach (var kv in gens.Select((g, i) => (g, i)))
            t = Regex.Replace(t, @"\b" + Regex.Escape(kv.g) + @"\b", args[kv.i]);
        return t;
    }

    // ---------- build ----------
    public void Finish()
    {
        foreach (var t in Types)
        {
            if (!ByName.TryGetValue(t.Name, out var l)) ByName[t.Name] = l = new();
            l.Add(t);
            if (!Canon.ContainsKey(t.Id)) Canon[t.Id] = t;
        }
        // merge partials: base / interfaces / generics onto canonical + siblings
        foreach (var grp in Types.GroupBy(t => t.Id))
        {
            var list = grp.ToList();
            if (list.Count < 2) continue;
            var withBase = list.FirstOrDefault(x => x.Base != null);
            var gens = list.FirstOrDefault(x => x.Generics != null)?.Generics;
            var ifs = list.SelectMany(x => x.Interfaces).Distinct().ToList();
            foreach (var x in list)
            {
                if (withBase != null && x.Base == null) { x.Base = withBase.Base; x.BaseName = withBase.BaseName; x.BaseArgs = withBase.BaseArgs; }
                x.Generics ??= gens;
                x.Interfaces = ifs.ToList();
            }
        }
        foreach (var f in Fields)
        {
            if (f.Type == null) continue;
            if (!FieldTypes.TryGetValue(f.Owner, out var d)) FieldTypes[f.Owner] = d = new();
            d.TryAdd(f.Name, f.Type);
        }
        foreach (var m in Methods)
        {
            if (!MethodNames.TryGetValue(m.Owner, out var hs)) MethodNames[m.Owner] = hs = new();
            hs.Add(m.Name);
            if (m.ReturnType == null) continue;
            if (!MethodRet.TryGetValue(m.Owner, out var d)) MethodRet[m.Owner] = d = new();
            d.TryAdd(m.Name, m.ReturnType);
        }
        // resolve bases (needs ByName + ancestors; memoised)
        foreach (var t in Types) ResolveBase(t, new HashSet<string>());
        // overrides
        foreach (var m in Methods.Where(m => m.Override))
        {
            if (!Canon.TryGetValue(m.Owner, out var o)) continue;
            string found = null, last = o.BaseName; var cur = o; int guard = 0;
            while (cur != null && guard++ < 40)
            {
                if (cur.BaseResolved != null && Canon.TryGetValue(cur.BaseResolved, out var b))
                {
                    if (MethodNames.TryGetValue(b.Id, out var hs) && hs.Contains(m.Name)) { found = b.Id + "." + m.Name; break; }
                    last = b.BaseName; cur = b;
                }
                else { last = cur.BaseName; break; }
            }
            m.OverrideOf = found ?? (last != null ? last + "." + m.Name : null);
        }
    }

    HashSet<string> OuterAncestors(TypeRec t)
    {
        var set = new HashSet<string>();
        var cur = t.Parent != null && Canon.TryGetValue(t.Parent, out var p) ? p : null;
        int guard = 0;
        while (cur != null && guard++ < 10)
        {
            var c = cur;
            int g2 = 0;
            while (c != null && g2++ < 40 && set.Add(c.Id))
            {
                c = c.BaseResolved != null && Canon.TryGetValue(c.BaseResolved, out var b) ? b : null;
            }
            cur = cur.Parent != null && Canon.TryGetValue(cur.Parent, out var pp) ? pp : null;
        }
        return set;
    }

    void ResolveBase(TypeRec t, HashSet<string> visiting)
    {
        if (t.BaseName == null || t.BaseResolved != null) return;
        if (!ByName.TryGetValue(t.BaseName, out var cands)) return;
        var cl = cands.Where(c => c.Kind != "interface" || t.Kind == "interface").GroupBy(c => c.Id).Select(g => g.First()).ToList();
        if (cl.Count == 0) return;
        if (cl.Count > 1)
        {
            int arity = t.BaseArgs.Count;
            var byArity = cl.Where(c => (c.Generics?.Count ?? 0) == arity).ToList();
            if (byArity.Count > 0) cl = byArity;
        }
        TypeRec pick = null;
        if (cl.Count == 1) pick = cl[0];
        else
        {
            pick = cl.FirstOrDefault(c => c.Parent == t.Parent && c.Parent != null);
            if (pick == null && visiting.Add(t.Id))
            {
                var anc = OuterAncestors(t);
                pick = cl.FirstOrDefault(c => c.Parent != null && anc.Contains(c.Parent));
            }
            pick ??= cl.FirstOrDefault(c => c.Parent == null) ?? cl.OrderBy(c => c.Id, StringComparer.Ordinal).First();
        }
        if (pick.Id != t.Id) t.BaseResolved = pick.Id;
    }

    // ---------- member lookup ----------
    /// <summary>Find member type (field/property type or method return type) in rec's hierarchy.</summary>
    public string Lookup(TypeRec rec, List<string> args, string member, bool method, int depth, out TypeRec declarer)
    {
        declarer = null;
        if (rec == null || depth > 20) return null;
        var tbl = method ? MethodRet : FieldTypes;
        if (tbl.TryGetValue(rec.Id, out var d) && d.TryGetValue(member, out var t))
        { declarer = rec; return Subst(t, rec.Generics, args); }
        if (method && MethodNames.TryGetValue(rec.Id, out var names) && names.Contains(member)) { declarer = rec; return null; }
        if (rec.Base != null)
        {
            var bargs = rec.BaseArgs.Select(a => Subst(a, rec.Generics, args)).ToList();
            TypeRec b = rec.BaseResolved != null && Canon.TryGetValue(rec.BaseResolved, out var bb) ? bb : null;
            if (b != null)
            {
                var r = Lookup(b, bargs, member, method, depth + 1, out declarer);
                if (r != null || declarer != null) return r;
            }
        }
        foreach (var i in rec.Interfaces)
        {
            var h = Head(i);
            if (h != null && ByName.TryGetValue(h, out var cands))
            {
                var c = cands.FirstOrDefault(x => x.Kind == "interface");
                if (c != null) { var r = Lookup(c, Args(i), member, method, depth + 1, out declarer); if (r != null || declarer != null) return r; }
            }
        }
        return null;
    }

    public string LookupByText(string typeText, string member, bool method, out TypeRec declarer)
    {
        declarer = null;
        var h = Head(typeText);
        if (h == null || !ByName.TryGetValue(h, out var cands)) return null;
        var args = Args(typeText);
        var seen = new HashSet<string>();
        foreach (var c in cands)
        {
            if (!seen.Add(c.Id)) continue;
            var r = Lookup(c, args, member, method, 0, out declarer);
            if (r != null || declarer != null) return r;
        }
        return null;
    }

    /// <summary>Implicit-this lookup: scope type, then lexically enclosing types.</summary>
    public string LookupImplicit(TypeRec scope, string member, bool method, out TypeRec declarer)
    {
        declarer = null;
        var cur = scope; int guard = 0;
        while (cur != null && guard++ < 12)
        {
            var r = Lookup(cur, null, member, method, 0, out declarer);
            if (r != null || declarer != null) return r;
            cur = cur.Parent != null && Canon.TryGetValue(cur.Parent, out var p) ? p : null;
        }
        return null;
    }

    public bool IsKnownType(string name) => ByName.ContainsKey(name);
    public bool IsEnum(string name) => ByName.TryGetValue(name, out var l) && l.Any(x => x.Kind == "enum");
}

