using System.Globalization;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace CodeIndex;

public class FileResult
{
    public List<TypeRec> Types = new();
    public List<FieldRec> Fields = new();
    public List<MethodRec> Methods = new();
    public List<LiteralRec> Literals = new();
    public int ParseErrors;
}

class Scope
{
    public TypeRec Type;
    public MethodRec Method;
    public string Owner;
    public string OwnerKind;
    public Dictionary<string, string> Locals;
    public Dictionary<string, CallRec> Dedupe;
}

/// <summary>
/// Walks one syntax tree. Phase 1 declares types/members (no bodies). Phase 2 scans bodies
/// (calls, literals) using the global Db for syntactic receiver-type resolution.
/// </summary>
public class Walker
{
    readonly Db db;
    readonly int fileIdx;
    readonly string rel;
    readonly SourceText text;
    readonly bool phase2;
    readonly FileResult res;
    readonly bool keepStrings;
    static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

    public Walker(Db db, int fileIdx, string rel, SourceText text, bool phase2, FileResult res, bool keepStrings)
    { this.db = db; this.fileIdx = fileIdx; this.rel = rel; this.text = text; this.phase2 = phase2; this.res = res; this.keepStrings = keepStrings; }

    int Line(int pos) => text.Lines.GetLinePosition(pos).Line + 1;

    public static string Compact(string s)
    {
        if (s == null) return null;
        var sb = new StringBuilder(s.Length);
        bool sp = false;
        foreach (var c in s)
        {
            if (char.IsWhiteSpace(c)) { sp = true; continue; }
            if (sp && sb.Length > 0) sb.Append(' ');
            sp = false; sb.Append(c);
        }
        return sb.ToString();
    }

    static string Cut(string s, int n) => s == null ? null : (s.Length <= n ? s : s[..(n - 1)] + "…");

    static int StartPos(MemberDeclarationSyntax m)
    {
        var al = m.AttributeLists;
        if (al.Count == 0) return m.SpanStart;
        var t = al[al.Count - 1].GetLastToken().GetNextToken();
        return t.IsKind(SyntaxKind.None) ? m.SpanStart : t.SpanStart;
    }

    static List<string> Mods(SyntaxTokenList l) => l.Select(t => t.Text).ToList();

    static List<string> Attrs(SyntaxList<AttributeListSyntax> lists)
    {
        var r = new List<string>();
        foreach (var l in lists) foreach (var a in l.Attributes) r.Add(Cut(Compact(a.ToString()), 100));
        return r.Count == 0 ? null : r;
    }

    // ============ structure ============
    public void Run(SyntaxNode root)
    {
        var cu = (CompilationUnitSyntax)root;
        WalkMembers(cu.Members, null, null);
    }

    void WalkMembers(SyntaxList<MemberDeclarationSyntax> members, string ns, TypeRec parent)
    {
        foreach (var m in members)
        {
            switch (m)
            {
                case BaseNamespaceDeclarationSyntax n:
                    WalkMembers(n.Members, ns == null ? n.Name.ToString() : ns + "." + n.Name, parent);
                    break;
                case BaseTypeDeclarationSyntax t:
                    DoType(t, ns, parent);
                    break;
                case DelegateDeclarationSyntax d:
                    DoDelegate(d, ns, parent);
                    break;
                default:
                    if (parent != null) DoMember(m, parent);
                    break;
            }
        }
    }

    static string TypeName(SyntaxToken id) => id.Text;

    void DoDelegate(DelegateDeclarationSyntax d, string ns, TypeRec parent)
    {
        if (phase2)
        {
            if (!db.TypeByPos.TryGetValue((fileIdx, d.SpanStart), out var rec0)) return;
            ScanNodes(new SyntaxNode[] { d.ParameterList }, new Scope { Type = rec0, Owner = rec0.Name, OwnerKind = "type" });
            return;
        }
        string name = d.Identifier.Text;
        var rec = new TypeRec
        {
            Id = parent != null ? parent.Id + "." + name : (ns != null ? ns + "." + name : name),
            Name = name, Kind = "delegate", File = rel, Namespace = ns, Parent = parent?.Id,
            LineStart = Line(StartPos(d)), LineEnd = Line(d.Span.End),
            Modifiers = Mods(d.Modifiers), Attributes = Attrs(d.AttributeLists),
            Signature = Cut(Compact(d.ReturnType + " " + d.Identifier.Text + d.TypeParameterList + d.ParameterList), 300),
            Pos = d.SpanStart, FileIdx = fileIdx
        };
        res.Types.Add(rec);
    }

    void DoType(BaseTypeDeclarationSyntax t, string ns, TypeRec parent)
    {
        TypeRec rec;
        if (phase2)
        {
            if (!db.TypeByPos.TryGetValue((fileIdx, t.SpanStart), out rec)) return;
            ScanAttrs(t.AttributeLists, new Scope { Type = rec, Owner = rec.Name, OwnerKind = "attribute" });
        }
        else
        {
            string name = t.Identifier.Text;
            string kind = t switch
            {
                EnumDeclarationSyntax => "enum",
                RecordDeclarationSyntax => "record",
                _ => t.Kind() switch
                {
                    SyntaxKind.StructDeclaration => "struct",
                    SyntaxKind.InterfaceDeclaration => "interface",
                    _ => "class"
                }
            };
            rec = new TypeRec
            {
                Id = parent != null ? parent.Id + "." + name : (ns != null ? ns + "." + name : name),
                Name = name, Kind = kind, File = rel, Namespace = ns, Parent = parent?.Id,
                LineStart = Line(StartPos(t)), LineEnd = Line(t.Span.End),
                Modifiers = Mods(t.Modifiers), Attributes = Attrs(t.AttributeLists),
                Pos = t.SpanStart, FileIdx = fileIdx
            };
            if (t is TypeDeclarationSyntax td && td.TypeParameterList != null)
                rec.Generics = td.TypeParameterList.Parameters.Select(p => p.Identifier.Text).ToList();
            if (t.BaseList != null)
            {
                bool first = true;
                foreach (var bt in t.BaseList.Types)
                {
                    var txt = Compact(bt.Type.ToString());
                    var head = Db.Head(txt) ?? txt;
                    bool looksIface = head.Length > 1 && head[0] == 'I' && char.IsUpper(head[1]);
                    if (first && (kind == "class" || kind == "record") && !looksIface)
                    { rec.Base = txt; rec.BaseName = head; rec.BaseArgs = Db.Args(txt); }
                    else if (kind == "interface" && first && false) { }
                    else rec.Interfaces.Add(txt);
                    first = false;
                }
            }
            if (t is EnumDeclarationSyntax ed) rec.Members = EnumMembers(ed);
            res.Types.Add(rec);
        }

        if (t is EnumDeclarationSyntax en)
        {
            if (phase2)
                foreach (var em in en.Members)
                    if (em.EqualsValue != null)
                        ScanNodes(new SyntaxNode[] { em.EqualsValue }, new Scope { Type = rec, Owner = em.Identifier.Text, OwnerKind = "enum" });
        }
        else if (t is TypeDeclarationSyntax tds)
        {
            if (phase2 && tds.ParameterList != null)
                ScanNodes(new SyntaxNode[] { tds.ParameterList }, new Scope { Type = rec, Owner = rec.Name, OwnerKind = "type" });
            WalkMembers(tds.Members, ns, rec);
        }
    }

    List<EnumMemberRec> EnumMembers(EnumDeclarationSyntax ed)
    {
        var list = new List<EnumMemberRec>();
        var vals = new Dictionary<string, long>();
        long next = 0; bool known = true;
        foreach (var m in ed.Members)
        {
            var r = new EnumMemberRec { Name = m.Identifier.Text, Line = Line(m.SpanStart) };
            if (m.EqualsValue != null)
            {
                r.Raw = Cut(Compact(m.EqualsValue.Value.ToString()), 80);
                var v = EvalInt(m.EqualsValue.Value, vals);
                if (v.HasValue) { next = v.Value; known = true; } else known = false;
            }
            if (known) { r.Value = next.ToString(Inv); vals[r.Name] = next; next++; }
            list.Add(r);
        }
        return list;
    }

    static long? EvalInt(ExpressionSyntax e, Dictionary<string, long> vals)
    {
        switch (e)
        {
            case LiteralExpressionSyntax l when l.IsKind(SyntaxKind.NumericLiteralExpression):
                try { return Convert.ToInt64(l.Token.Value, Inv); } catch { return null; }
            case ParenthesizedExpressionSyntax p: return EvalInt(p.Expression, vals);
            case CastExpressionSyntax c: return EvalInt(c.Expression, vals);
            case IdentifierNameSyntax id: return vals.TryGetValue(id.Identifier.Text, out var v) ? v : null;
            case PrefixUnaryExpressionSyntax u:
                {
                    var x = EvalInt(u.Operand, vals);
                    if (x == null) return null;
                    return u.Kind() switch { SyntaxKind.UnaryMinusExpression => -x, SyntaxKind.BitwiseNotExpression => ~x, SyntaxKind.UnaryPlusExpression => x, _ => null };
                }
            case BinaryExpressionSyntax b:
                {
                    var l = EvalInt(b.Left, vals); var r = EvalInt(b.Right, vals);
                    if (l == null || r == null) return null;
                    return b.Kind() switch
                    {
                        SyntaxKind.BitwiseOrExpression => l | r,
                        SyntaxKind.BitwiseAndExpression => l & r,
                        SyntaxKind.ExclusiveOrExpression => l ^ r,
                        SyntaxKind.LeftShiftExpression => l << (int)r,
                        SyntaxKind.RightShiftExpression => l >> (int)r,
                        SyntaxKind.AddExpression => l + r,
                        SyntaxKind.SubtractExpression => l - r,
                        SyntaxKind.MultiplyExpression => l * r,
                        _ => null
                    };
                }
        }
        return null;
    }

    // ============ members ============
    void DoMember(MemberDeclarationSyntax m, TypeRec owner)
    {
        switch (m)
        {
            case FieldDeclarationSyntax f: DoField(f.Declaration, f.Modifiers, f.AttributeLists, owner, "field", f); break;
            case EventFieldDeclarationSyntax ef: DoField(ef.Declaration, ef.Modifiers, ef.AttributeLists, owner, "event", ef); break;
            case PropertyDeclarationSyntax p: DoProperty(p, owner, p.Identifier.Text, p.Type, p.Modifiers, p.AttributeLists, p.AccessorList, p.ExpressionBody, p.Initializer); break;
            case IndexerDeclarationSyntax ix: DoProperty(ix, owner, "this[]", ix.Type, ix.Modifiers, ix.AttributeLists, ix.AccessorList, ix.ExpressionBody, null); break;
            case EventDeclarationSyntax ev: DoProperty(ev, owner, ev.Identifier.Text, ev.Type, ev.Modifiers, ev.AttributeLists, ev.AccessorList, null, null, "event"); break;
            case MethodDeclarationSyntax md:
                DoMethod(md, owner, md.Identifier.Text, "method", Compact(md.ReturnType.ToString()), md.Modifiers, md.AttributeLists,
                    Compact(md.ReturnType + " " + md.Identifier.Text + md.TypeParameterList + md.ParameterList), md.ParameterList, md.Body, md.ExpressionBody, null);
                break;
            case ConstructorDeclarationSyntax cd:
                DoMethod(cd, owner, ".ctor", "ctor", null, cd.Modifiers, cd.AttributeLists,
                    Compact(cd.Identifier.Text + cd.ParameterList), cd.ParameterList, cd.Body, cd.ExpressionBody, cd.Initializer);
                break;
            case DestructorDeclarationSyntax dd:
                DoMethod(dd, owner, ".dtor", "dtor", null, dd.Modifiers, dd.AttributeLists, "~" + dd.Identifier.Text + "()", dd.ParameterList, dd.Body, dd.ExpressionBody, null);
                break;
            case OperatorDeclarationSyntax od:
                DoMethod(od, owner, "operator " + od.OperatorToken.Text, "operator", Compact(od.ReturnType.ToString()), od.Modifiers, od.AttributeLists,
                    Compact(od.ReturnType + " operator " + od.OperatorToken.Text + od.ParameterList), od.ParameterList, od.Body, od.ExpressionBody, null);
                break;
            case ConversionOperatorDeclarationSyntax co:
                DoMethod(co, owner, "operator " + co.Type, "conversion", Compact(co.Type.ToString()), co.Modifiers, co.AttributeLists,
                    Compact(co.ImplicitOrExplicitKeyword.Text + " operator " + co.Type + co.ParameterList), co.ParameterList, co.Body, co.ExpressionBody, null);
                break;
        }
    }

    void DoField(VariableDeclarationSyntax decl, SyntaxTokenList mods, SyntaxList<AttributeListSyntax> attrs, TypeRec owner, string kind, MemberDeclarationSyntax member)
    {
        string type = Compact(decl.Type.ToString());
        foreach (var v in decl.Variables)
        {
            if (phase2)
            {
                if (v.Initializer != null)
                    ScanNodes(new SyntaxNode[] { v }, new Scope { Type = owner, Owner = v.Identifier.Text, OwnerKind = "field" });
                continue;
            }
            var ml = Mods(mods);
            bool isConst = ml.Contains("const");
            var f = new FieldRec
            {
                Owner = owner.Id, Name = v.Identifier.Text, Kind = kind, Type = type, Modifiers = ml,
                Static = ml.Contains("static") || isConst, Const = isConst, Readonly = ml.Contains("readonly"),
                File = rel, Line = Line(v.SpanStart), Attributes = Attrs(attrs)
            };
            if (v.Initializer != null)
            {
                f.Initializer = LiteralValue(v.Initializer.Value);
                f.InitExpr = Cut(Compact(v.Initializer.Value.ToString()), 120);
            }
            res.Fields.Add(f);
        }
    }

    static string LiteralValue(ExpressionSyntax e)
    {
        bool neg = false;
        while (e is ParenthesizedExpressionSyntax p) e = p.Expression;
        if (e is PrefixUnaryExpressionSyntax u && u.IsKind(SyntaxKind.UnaryMinusExpression)) { neg = true; e = u.Operand; }
        if (e is LiteralExpressionSyntax l)
        {
            if (l.IsKind(SyntaxKind.NumericLiteralExpression)) { var d = NumValue(l.Token); if (d == null) return null; return Fmt(neg ? -d.Value : d.Value); }
            if (l.IsKind(SyntaxKind.StringLiteralExpression)) return Cut(l.Token.ValueText, 200);
            if (l.IsKind(SyntaxKind.TrueLiteralExpression)) return "true";
            if (l.IsKind(SyntaxKind.FalseLiteralExpression)) return "false";
            if (l.IsKind(SyntaxKind.NullLiteralExpression)) return "null";
            if (l.IsKind(SyntaxKind.CharacterLiteralExpression)) return l.Token.ValueText;
        }
        return null;
    }

    static string Fmt(double d)
    {
        if (d == Math.Floor(d) && Math.Abs(d) < 1e15) return ((long)d).ToString(Inv);
        return d.ToString("R", Inv);
    }

    static double? NumValue(SyntaxToken tok)
    {
        var txt = tok.Text.Replace("_", "");
        bool hex = txt.StartsWith("0x", StringComparison.OrdinalIgnoreCase) || txt.StartsWith("0b", StringComparison.OrdinalIgnoreCase);
        if (!hex)
        {
            int end = txt.Length;
            while (end > 0 && "fFdDmMlLuU".IndexOf(txt[end - 1]) >= 0) end--;
            if (double.TryParse(txt[..end], NumberStyles.Float, Inv, out var d)) return d;
        }
        try { return Convert.ToDouble(tok.Value, Inv); } catch { return null; }
    }

    void DoProperty(MemberDeclarationSyntax m, TypeRec owner, string name, TypeSyntax type, SyntaxTokenList mods,
        SyntaxList<AttributeListSyntax> attrs, AccessorListSyntax accessors, ArrowExpressionClauseSyntax arrow, EqualsValueClauseSyntax init, string kind = "property")
    {
        if (!phase2)
        {
            var ml = Mods(mods);
            var f = new FieldRec
            {
                Owner = owner.Id, Name = name, Kind = kind, Type = Compact(type.ToString()), Modifiers = ml,
                Static = ml.Contains("static"), File = rel, Line = Line(StartPos(m)), Attributes = Attrs(attrs)
            };
            if (init != null) { f.Initializer = LiteralValue(init.Value); f.InitExpr = Cut(Compact(init.Value.ToString()), 120); }
            res.Fields.Add(f);
        }
        else if (init != null)
            ScanNodes(new SyntaxNode[] { init }, new Scope { Type = owner, Owner = name, OwnerKind = "property" });

        var ptype = Compact(type.ToString());
        if (accessors != null)
        {
            foreach (var a in accessors.Accessors)
            {
                string an = a.Keyword.Text;
                DoMethod(a, owner, name + "." + an, "accessor", an == "get" ? ptype : null, a.Modifiers, a.AttributeLists,
                    Compact(ptype + " " + name + "." + an), null, a.Body, a.ExpressionBody, null);
            }
        }
        if (arrow != null)
            DoMethod(arrow, owner, name + ".get", "accessor", ptype, mods, default, Compact(ptype + " " + name + ".get"), null, null, arrow, null, arrowNode: true);
    }

    void DoMethod(SyntaxNode node, TypeRec owner, string name, string kind, string retType, SyntaxTokenList mods,
        SyntaxList<AttributeListSyntax> attrs, string signature, ParameterListSyntax plist, BlockSyntax body, ArrowExpressionClauseSyntax arrow,
        ConstructorInitializerSyntax ctorInit, bool arrowNode = false)
    {
        MethodRec rec;
        if (!phase2)
        {
            if (body == null && arrow == null && kind != "ctor") { /* abstract/extern/interface: still record the declaration */ }
            var ml = Mods(mods);
            rec = new MethodRec
            {
                Owner = owner.Id, Name = name, Kind = kind, Signature = Cut(signature, 400), Modifiers = ml,
                File = rel, LineStart = Line(node is MemberDeclarationSyntax md ? StartPos(md) : node.SpanStart), LineEnd = Line(node.Span.End),
                Override = ml.Contains("override"), Attributes = attrs.Count > 0 ? Attrs(attrs) : null,
                ReturnType = retType, ParamCount = plist?.Parameters.Count ?? 0, Pos = node.SpanStart, FileIdx = fileIdx
            };
            res.Methods.Add(rec);
            return;
        }
        if (!db.MethodByPos.TryGetValue((fileIdx, node.SpanStart), out rec)) return;
        if (attrs.Count > 0) ScanAttrs(attrs, new Scope { Type = owner, Owner = name, OwnerKind = "attribute" });
        var sc = new Scope { Type = owner, Method = rec, Owner = name, OwnerKind = "method", Locals = new(), Dedupe = new() };
        if (plist != null)
            foreach (var p in plist.Parameters)
                if (p.Type != null) sc.Locals[p.Identifier.Text] = Compact(p.Type.ToString());
        if (name.EndsWith(".set") || name.EndsWith(".init")) sc.Locals["value"] = null;
        var roots = new List<SyntaxNode>();
        if (plist != null) roots.Add(plist);
        if (ctorInit != null) roots.Add(ctorInit);
        if (body != null) roots.Add(body);
        if (arrow != null) roots.Add(arrow);
        ScanNodes(roots, sc);
        foreach (var c in sc.Dedupe.Values) rec.Calls.Add(c);
        rec.Calls.Sort((a, b) => a.Line != b.Line ? a.Line.CompareTo(b.Line) : string.CompareOrdinal(a.Name, b.Name));
    }

    // ============ phase 2: scanning ============
    void ScanAttrs(SyntaxList<AttributeListSyntax> attrs, Scope sc)
    {
        if (attrs.Count == 0) return;
        sc.OwnerKind = "attribute";
        foreach (var l in attrs) ScanNodes(new SyntaxNode[] { l }, sc, true);
    }

    void ScanNodes(IEnumerable<SyntaxNode> roots, Scope sc, bool intoAttrs = false)
    {
        foreach (var root in roots)
        {
            foreach (var n in root.DescendantNodesAndSelf(d => intoAttrs || d is not AttributeListSyntax))
            {
                switch (n)
                {
                    case VariableDeclaratorSyntax vd when sc.Locals != null && vd.Parent is VariableDeclarationSyntax vdecl:
                        if (vdecl.Type.IsVar) { var t = vd.Initializer != null ? Resolve(vd.Initializer.Value, sc, 0) : null; sc.Locals[vd.Identifier.Text] = t; }
                        else sc.Locals[vd.Identifier.Text] = Compact(vdecl.Type.ToString());
                        break;
                    case ParameterSyntax p when sc.Locals != null && p.Type != null:
                        sc.Locals[p.Identifier.Text] = Compact(p.Type.ToString());
                        break;
                    case ForEachStatementSyntax fe when sc.Locals != null:
                        sc.Locals[fe.Identifier.Text] = fe.Type.IsVar ? Db.ElemType(Resolve(fe.Expression, sc, 0)) : Compact(fe.Type.ToString());
                        break;
                    case DeclarationPatternSyntax dp when sc.Locals != null && dp.Designation is SingleVariableDesignationSyntax sv:
                        sc.Locals[sv.Identifier.Text] = Compact(dp.Type.ToString());
                        break;
                    case DeclarationExpressionSyntax de when sc.Locals != null && de.Designation is SingleVariableDesignationSyntax sv2 && !de.Type.IsVar:
                        sc.Locals[sv2.Identifier.Text] = Compact(de.Type.ToString());
                        break;
                    case InvocationExpressionSyntax inv when sc.Dedupe != null:
                        AddCall(inv, sc);
                        break;
                    case ObjectCreationExpressionSyntax oc when sc.Dedupe != null:
                        AddCtor(oc.Type, oc.SpanStart, sc);
                        break;
                    case LiteralExpressionSyntax lit:
                        AddLiteral(lit, sc);
                        break;
                }
            }
        }
    }

    void AddCtor(TypeSyntax type, int pos, Scope sc)
    {
        var tt = Compact(type.ToString());
        Bump(sc, ".ctor", null, Db.Head(tt) ?? tt, Line(pos));
    }

    static void Bump(Scope sc, string name, string recv, string rt, int line)
    {
        var key = name + "|" + recv + "|" + rt;
        if (sc.Dedupe.TryGetValue(key, out var c)) { c.Count++; return; }
        sc.Dedupe[key] = new CallRec { Name = name, Receiver = recv, ReceiverType = rt, Line = line };
    }

    static readonly HashSet<string> GenericReturnsT = new() { "GetComponent", "GetComponentInChildren", "GetComponentInParent", "FindObjectOfType", "FindFirstObjectByType", "FindAnyObjectByType", "AddComponent", "Load" };
    static readonly HashSet<string> GenericReturnsArr = new() { "GetComponents", "GetComponentsInChildren", "GetComponentsInParent", "FindObjectsOfType" };

    void AddCall(InvocationExpressionSyntax inv, Scope sc)
    {
        int line = Line(inv.SpanStart);
        switch (inv.Expression)
        {
            case IdentifierNameSyntax id:
                {
                    db.LookupImplicit(sc.Type, id.Identifier.Text, true, out var decl);
                    Bump(sc, id.Identifier.Text, null, decl?.Name, line);
                    break;
                }
            case GenericNameSyntax gn:
                {
                    db.LookupImplicit(sc.Type, gn.Identifier.Text, true, out var decl);
                    Bump(sc, gn.Identifier.Text, null, decl?.Name, line);
                    break;
                }
            case MemberAccessExpressionSyntax ma:
                {
                    var rt = Resolve(ma.Expression, sc, 0);
                    var recv = Cut(Compact(ma.Expression.ToString()), 60);
                    Bump(sc, ma.Name.Identifier.Text, recv, Db.Head(rt), line);
                    break;
                }
            case MemberBindingExpressionSyntax mb:
                {
                    var ca = inv.Ancestors().OfType<ConditionalAccessExpressionSyntax>().FirstOrDefault();
                    string rt = null, recv = null;
                    if (ca != null) { rt = Resolve(ca.Expression, sc, 0); recv = Cut(Compact(ca.Expression.ToString()), 60); }
                    Bump(sc, mb.Name.Identifier.Text, recv, Db.Head(rt), line);
                    break;
                }
        }
    }

    // ---- syntactic expression type resolver (heuristic) ----
    string Resolve(ExpressionSyntax e, Scope sc, int depth)
    {
        if (e == null || depth > 8) return null;
        switch (e)
        {
            case ParenthesizedExpressionSyntax p: return Resolve(p.Expression, sc, depth + 1);
            case ThisExpressionSyntax: return sc.Type?.Name;
            case BaseExpressionSyntax: return sc.Type?.BaseName;
            case IdentifierNameSyntax id:
                {
                    var n = id.Identifier.Text;
                    if (sc.Locals != null && sc.Locals.TryGetValue(n, out var lt)) return lt;
                    var ft = db.LookupImplicit(sc.Type, n, false, out var d);
                    if (ft != null) return ft;
                    if (d != null) return null;
                    if (db.IsKnownType(n) || (n.Length > 0 && char.IsUpper(n[0]))) return n; // static reference
                    return null;
                }
            case MemberAccessExpressionSyntax ma:
                {
                    var lt = Resolve(ma.Expression, sc, depth + 1);
                    if (lt == null) return null;
                    var name = ma.Name.Identifier.Text;
                    var h = Db.Head(lt);
                    if (h != null && db.IsEnum(h)) return h;
                    return db.LookupByText(lt, name, false, out _);
                }
            case InvocationExpressionSyntax inv:
                {
                    switch (inv.Expression)
                    {
                        case IdentifierNameSyntax id: return db.LookupImplicit(sc.Type, id.Identifier.Text, true, out _);
                        case GenericNameSyntax gn:
                            {
                                var tn = gn.Identifier.Text;
                                var ta = gn.TypeArgumentList.Arguments.Count == 1 ? Compact(gn.TypeArgumentList.Arguments[0].ToString()) : null;
                                if (ta != null && GenericReturnsT.Contains(tn)) return ta;
                                if (ta != null && GenericReturnsArr.Contains(tn)) return ta + "[]";
                                return db.LookupImplicit(sc.Type, tn, true, out _);
                            }
                        case MemberAccessExpressionSyntax ma:
                            {
                                var tn = ma.Name.Identifier.Text;
                                if (ma.Name is GenericNameSyntax g2 && g2.TypeArgumentList.Arguments.Count == 1)
                                {
                                    var ta = Compact(g2.TypeArgumentList.Arguments[0].ToString());
                                    if (GenericReturnsT.Contains(tn)) return ta;
                                    if (GenericReturnsArr.Contains(tn)) return ta + "[]";
                                }
                                if (tn == "Instantiate" && inv.ArgumentList.Arguments.Count > 0) return Resolve(inv.ArgumentList.Arguments[0].Expression, sc, depth + 1);
                                var lt = Resolve(ma.Expression, sc, depth + 1);
                                if (lt == null) return null;
                                var h = Db.Head(lt);
                                if ((h == "List" || h == "Queue" || h == "Stack" || h == "HashSet") && (tn == "Find" || tn == "FirstOrDefault" || tn == "First" || tn == "Dequeue" || tn == "Pop" || tn == "Peek")) return Db.ElemType(lt);
                                return db.LookupByText(lt, tn, true, out _);
                            }
                    }
                    return null;
                }
            case ObjectCreationExpressionSyntax oc: return Compact(oc.Type.ToString());
            case CastExpressionSyntax c: return Compact(c.Type.ToString());
            case BinaryExpressionSyntax b when b.IsKind(SyntaxKind.AsExpression): return Compact(((TypeSyntax)b.Right).ToString());
            case ElementAccessExpressionSyntax ea: return Db.ElemType(Resolve(ea.Expression, sc, depth + 1));
            case ConditionalAccessExpressionSyntax ca:
                {
                    var lt = Resolve(ca.Expression, sc, depth + 1);
                    if (lt == null) return null;
                    switch (ca.WhenNotNull)
                    {
                        case MemberBindingExpressionSyntax mb: return db.LookupByText(lt, mb.Name.Identifier.Text, false, out _);
                        case InvocationExpressionSyntax { Expression: MemberBindingExpressionSyntax mb2 }: return db.LookupByText(lt, mb2.Name.Identifier.Text, true, out _);
                    }
                    return null;
                }
            case PostfixUnaryExpressionSyntax pu when pu.IsKind(SyntaxKind.SuppressNullableWarningExpression): return Resolve(pu.Operand, sc, depth + 1);
            case LiteralExpressionSyntax: return null;
        }
        return null;
    }

    // ---- literals ----
    void AddLiteral(LiteralExpressionSyntax lit, Scope sc)
    {
        bool isNum = lit.IsKind(SyntaxKind.NumericLiteralExpression);
        bool isStr = lit.IsKind(SyntaxKind.StringLiteralExpression);
        if (!isNum && !isStr) return;
        if (isStr && (!keepStrings || lit.Token.ValueText.Length == 0)) return;
        SyntaxNode node = lit; bool neg = false;
        if (isNum && lit.Parent is PrefixUnaryExpressionSyntax u && u.IsKind(SyntaxKind.UnaryMinusExpression)) { node = u; neg = true; }
        var rec = new LiteralRec
        {
            Kind = isNum ? "num" : "str",
            OwnerType = sc.Type?.Id, Owner = sc.Owner, OwnerKind = sc.OwnerKind, File = rel, Line = Line(lit.SpanStart)
        };
        if (isNum)
        {
            var v = NumValue(lit.Token);
            if (v == null) return;
            rec.Value = Fmt(neg ? -v.Value : v.Value);
            rec.Text = (neg ? "-" : "") + lit.Token.Text;
        }
        else rec.Value = Cut(lit.Token.ValueText.Replace("\r", " ").Replace("\n", " "), 200);
        rec.Expr = ExprText(node);
        rec.Context = Context(node);
        res.Literals.Add(rec);
    }

    string ExprText(SyntaxNode node)
    {
        SyntaxNode anc = null; int start = 0, end = 0;
        foreach (var a in node.Ancestors())
        {
            if (a is CaseSwitchLabelSyntax || a is CasePatternSwitchLabelSyntax) { anc = a; start = a.SpanStart; end = a.Span.End; break; }
            if (a is StatementSyntax st && st is not BlockSyntax)
            {
                anc = a; start = a.SpanStart; end = a.Span.End;
                int? he = st switch
                {
                    IfStatementSyntax s => s.Statement.SpanStart,
                    WhileStatementSyntax s => s.Statement.SpanStart,
                    ForStatementSyntax s => s.Statement.SpanStart,
                    ForEachStatementSyntax s => s.Statement.SpanStart,
                    UsingStatementSyntax s => s.Statement.SpanStart,
                    LockStatementSyntax s => s.Statement.SpanStart,
                    FixedStatementSyntax s => s.Statement.SpanStart,
                    SwitchStatementSyntax s => s.OpenBraceToken.SpanStart,
                    DoStatementSyntax s => s.WhileKeyword.SpanStart,
                    _ => null
                };
                if (he.HasValue)
                {
                    if (st is DoStatementSyntax d) start = d.WhileKeyword.SpanStart;
                    else end = he.Value;
                }
                break;
            }
            if (a is ArrowExpressionClauseSyntax || a is EnumMemberDeclarationSyntax || a is ParameterSyntax || a is AttributeSyntax || a is VariableDeclaratorSyntax && a.Parent?.Parent is FieldDeclarationSyntax or EventFieldDeclarationSyntax)
            { anc = a; start = a.SpanStart; end = a.Span.End; break; }
            if (a is MemberDeclarationSyntax) { anc = a; start = node.SpanStart; end = node.Span.End; break; }
        }
        if (anc == null) { start = node.SpanStart; end = node.Span.End; }
        var full = text.ToString(new TextSpan(start, Math.Max(0, end - start)));
        var c = Compact(full);
        if (c.Length <= 120) return c;
        int ls = Math.Max(start, node.SpanStart - 70), le = Math.Min(end, node.Span.End + 50);
        var w = Compact(text.ToString(new TextSpan(ls, le - ls)));
        if (ls > start) w = "…" + w;
        if (le < end) w += "…";
        return Cut(w, 120);
    }

    static string CalleeName(SyntaxNode call) => call switch
    {
        InvocationExpressionSyntax i => i.Expression switch
        {
            IdentifierNameSyntax x => x.Identifier.Text,
            GenericNameSyntax g => g.Identifier.Text,
            MemberAccessExpressionSyntax m => m.Name.Identifier.Text,
            MemberBindingExpressionSyntax mb => mb.Name.Identifier.Text,
            _ => "(call)"
        },
        ObjectCreationExpressionSyntax o => "new " + (Db.Head(o.Type.ToString()) ?? "?"),
        ConstructorInitializerSyntax ci => ci.ThisOrBaseKeyword.Text,
        _ => "[]"
    };

    static string Context(SyntaxNode start)
    {
        SyntaxNode cur = start;
        while (cur.Parent != null)
        {
            var p = cur.Parent;
            switch (p)
            {
                case ArgumentSyntax arg when arg.Parent is BaseArgumentListSyntax al:
                    {
                        var callee = CalleeName(al.Parent);
                        int idx = al.Arguments.IndexOf(arg);
                        var sb = new StringBuilder(callee).Append('(');
                        if (idx > 0) sb.Append("…, ");
                        if (arg.NameColon != null) sb.Append(arg.NameColon.Name.Identifier.Text).Append(": ");
                        sb.Append(Cut(Compact(arg.Expression.ToString()), 40));
                        if (idx < al.Arguments.Count - 1) sb.Append(", …");
                        sb.Append(')');
                        return sb.ToString();
                    }
                case AssignmentExpressionSyntax asg when asg.Right == cur:
                    return Cut(Compact(asg.Left.ToString()), 50) + " " + asg.OperatorToken.Text;
                case EqualsValueClauseSyntax ev:
                    {
                        string nm = ev.Parent switch
                        {
                            VariableDeclaratorSyntax vd => vd.Identifier.Text,
                            ParameterSyntax pa => "param " + pa.Identifier.Text,
                            PropertyDeclarationSyntax pr => pr.Identifier.Text,
                            EnumMemberDeclarationSyntax em => em.Identifier.Text,
                            _ => "init"
                        };
                        return nm + " =";
                    }
                case ReturnStatementSyntax: return "return";
                case ArrowExpressionClauseSyntax: return "return";
                case CaseSwitchLabelSyntax: return "case";
                case BinaryExpressionSyntax b when b.Kind() is SyntaxKind.LessThanExpression or SyntaxKind.GreaterThanExpression or SyntaxKind.LessThanOrEqualExpression
                    or SyntaxKind.GreaterThanOrEqualExpression or SyntaxKind.EqualsExpression or SyntaxKind.NotEqualsExpression:
                    return b.Left == cur ? "cmp: " + b.OperatorToken.Text + " " + Cut(Compact(b.Right.ToString()), 30) : "cmp: " + Cut(Compact(b.Left.ToString()), 30) + " " + b.OperatorToken.Text;
                case AttributeArgumentSyntax aa when aa.Parent?.Parent is AttributeSyntax at:
                    return at.Name + "(…)";
                case InitializerExpressionSyntax: return "initializer";
                case StatementSyntax: return "stmt";
                case MemberDeclarationSyntax: return "expr";
            }
            cur = p;
        }
        return "expr";
    }
}

