using System.Diagnostics;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Text;

namespace CodeIndex;

public static class Program
{
    const string Version = "1.0";

    static int Usage()
    {
        Console.Error.WriteLine(@"codeindex <src_dir> -o <out_dir> [options]

  <src_dir>          folder with .cs files (searched recursively)
  -o, --out <dir>    output folder (index.json [+ index.sqlite]); default: ./index
  --sqlite           also write index.sqlite
  --no-strings       do not index string literals
  --state-base NAME  base type name that marks FSM state classes (default: State)
  --threads N        parallelism (default: all cores)
  -q, --quiet        no progress output");
        return 2;
    }

    public static int Main(string[] args)
    {
        string src = null, outDir = "index", stateBase = "State";
        bool sqlite = false, strings = true, quiet = false; int threads = Environment.ProcessorCount;
        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "-o": case "--out": outDir = args[++i]; break;
                case "--sqlite": sqlite = true; break;
                case "--no-strings": strings = false; break;
                case "--state-base": stateBase = args[++i]; break;
                case "--threads": threads = int.Parse(args[++i]); break;
                case "-q": case "--quiet": quiet = true; break;
                case "-h": case "--help": return Usage();
                default: if (src == null && !args[i].StartsWith("-")) src = args[i]; else return Usage(); break;
            }
        }
        if (src == null || !Directory.Exists(src)) { Console.Error.WriteLine("src_dir not found"); return Usage(); }
        src = Path.GetFullPath(src);
        Directory.CreateDirectory(outDir);
        var sw = Stopwatch.StartNew();
        void Log(string s) { if (!quiet) Console.WriteLine($"[{sw.Elapsed.TotalSeconds,6:F1}s] {s}"); }

        var files = Directory.EnumerateFiles(src, "*.cs", SearchOption.AllDirectories)
            .Where(f => !f.Contains(Path.DirectorySeparatorChar + "obj" + Path.DirectorySeparatorChar))
            .OrderBy(f => f, StringComparer.Ordinal).ToList();
        var db = new Db();
        foreach (var f in files) db.Files.Add(Path.GetRelativePath(src, f).Replace('\\', '/'));
        Log($"{files.Count} files");

        var popt = new ParallelOptions { MaxDegreeOfParallelism = Math.Max(1, threads) };
        var parseOpts = new CSharpParseOptions(LanguageVersion.Latest, DocumentationMode.None);
        var results = new FileResult[files.Count];
        var failed = new System.Collections.Concurrent.ConcurrentBag<string>();
        var errFiles = new System.Collections.Concurrent.ConcurrentBag<(string, int)>();

        (SourceText, SyntaxTree) Parse(int i)
        {
            string txt;
            using (var rd = new StreamReader(files[i], Encoding.UTF8, true)) txt = rd.ReadToEnd();
            var st = SourceText.From(txt);
            return (st, CSharpSyntaxTree.ParseText(st, parseOpts, files[i]));
        }

        // phase 1
        Parallel.For(0, files.Count, popt, i =>
        {
            try
            {
                var (st, tree) = Parse(i);
                var r = new FileResult();
                new Walker(db, i, db.Files[i], st, false, r, strings).Run(tree.GetRoot());
                r.ParseErrors = tree.GetDiagnostics().Count(d => d.Severity == DiagnosticSeverity.Error);
                if (r.ParseErrors > 0) errFiles.Add((db.Files[i], r.ParseErrors));
                results[i] = r;
            }
            catch (Exception ex) { failed.Add(db.Files[i] + ": " + ex.GetType().Name + " " + ex.Message); results[i] = new FileResult(); }
        });
        foreach (var r in results)
        {
            db.Types.AddRange(r.Types); db.Fields.AddRange(r.Fields); db.Methods.AddRange(r.Methods);
        }
        foreach (var t in db.Types) db.TypeByPos[(t.FileIdx, t.Pos)] = t;
        foreach (var m in db.Methods) db.MethodByPos[(m.FileIdx, m.Pos)] = m;
        db.Finish();
        Log($"phase 1: {db.Types.Count} types, {db.Fields.Count} fields/props, {db.Methods.Count} methods");

        // phase 2
        Parallel.For(0, files.Count, popt, i =>
        {
            try
            {
                var (st, tree) = Parse(i);
                new Walker(db, i, db.Files[i], st, true, results[i], strings).Run(tree.GetRoot());
            }
            catch (Exception ex) { failed.Add(db.Files[i] + " (phase2): " + ex.GetType().Name + " " + ex.Message); }
        });
        var literals = results.SelectMany(r => r.Literals).ToList();
        Log($"phase 2: {literals.Count} literals, {db.Methods.Sum(m => m.Calls.Count)} call sites");

        // tidy empties
        foreach (var t in db.Types) { if (t.Modifiers.Count == 0) t.Modifiers = null; if (t.Interfaces.Count == 0) t.Interfaces = null; }
        foreach (var f in db.Fields) if (f.Modifiers.Count == 0) f.Modifiers = null;
        foreach (var m in db.Methods) { if (m.Modifiers.Count == 0) m.Modifiers = null; if (m.Calls.Count == 0) m.Calls = null; }

        var derived = Derive(db, stateBase);
        Log($"derived: {derived.StateClasses.Count} state classes, {derived.EnumValues.Count} enums");

        var stats = new Dictionary<string, object>
        {
            ["files"] = files.Count,
            ["types"] = db.Types.Count,
            ["fields"] = db.Fields.Count,
            ["methods"] = db.Methods.Count,
            ["call_sites"] = db.Methods.Sum(m => m.Calls?.Count ?? 0),
            ["calls_with_receiver_type"] = db.Methods.Sum(m => m.Calls?.Count(c => c.ReceiverType != null) ?? 0),
            ["literals_num"] = literals.Count(l => l.Kind == "num"),
            ["literals_str"] = literals.Count(l => l.Kind == "str"),
            ["state_classes"] = derived.StateClasses.Count,
            ["files_with_parse_errors"] = errFiles.Count,
            ["parse_error_total"] = errFiles.Sum(e => e.Item2),
            ["files_failed"] = failed.Count,
        };
        var meta = new Dictionary<string, object>
        {
            ["tool"] = "codeindex " + Version,
            ["src_dir"] = src.Replace('\\', '/'),
            ["generated_utc"] = DateTime.UtcNow.ToString("o"),
            ["state_base"] = stateBase,
            ["stats"] = stats,
            ["parse_error_files"] = errFiles.OrderByDescending(e => e.Item2).Take(30).Select(e => new { file = e.Item1, errors = e.Item2 }).ToList(),
            ["failed_files"] = failed.ToList(),
        };

        // output
        var jopt = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
            DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
            WriteIndented = false
        };
        var jsonPath = Path.Combine(outDir, "index.json");
        using (var w = new StreamWriter(jsonPath, false, new UTF8Encoding(false), 1 << 20))
        {
            w.Write("{\n\"meta\": " + JsonSerializer.Serialize(meta, jopt) + ",\n");
            WriteArr(w, "types", db.Types, jopt, false);
            WriteArr(w, "fields", db.Fields, jopt, false);
            WriteArr(w, "methods", db.Methods, jopt, false);
            WriteArr(w, "literals", literals, jopt, false);
            w.Write("\"derived\": " + JsonSerializer.Serialize(derived, jopt) + "\n}\n");
        }
        Log($"wrote {jsonPath} ({new FileInfo(jsonPath).Length / 1048576.0:F1} MB)");
        if (sqlite)
        {
            SqliteOut.Write(Path.Combine(outDir, "index.sqlite"), db, literals, derived);
            Log("wrote index.sqlite");
        }
        sw.Stop();
        Console.WriteLine($"OK files={files.Count} types={db.Types.Count} fields={db.Fields.Count} methods={db.Methods.Count} " +
            $"calls={stats["call_sites"]} literals={literals.Count} (num={stats["literals_num"]}, str={stats["literals_str"]}) " +
            $"state_classes={derived.StateClasses.Count} parse_error_files={errFiles.Count} failed={failed.Count} time={sw.Elapsed.TotalSeconds:F1}s");
        foreach (var f in failed.Take(10)) Console.Error.WriteLine("FAILED " + f);
        return 0;
    }

    static void WriteArr<T>(StreamWriter w, string name, List<T> items, JsonSerializerOptions o, bool last)
    {
        w.Write("\"" + name + "\": [\n");
        for (int i = 0; i < items.Count; i++)
        {
            w.Write(JsonSerializer.Serialize(items[i], o));
            w.Write(i < items.Count - 1 ? ",\n" : "\n");
        }
        w.Write(last ? "]\n" : "],\n");
    }

    // ============ derived ============
    public class StateClass
    {
        public string Type { get; set; }
        public string Parent { get; set; }
        public string StateBase { get; set; }
        public string OwnerGeneric { get; set; }
        public List<string> Chain { get; set; }
        public string File { get; set; }
        public int LineStart { get; set; }
        public int LineEnd { get; set; }
    }

    public class Derived
    {
        public List<string> Roots { get; set; }
        public Dictionary<string, List<string>> Subclasses { get; set; }
        public Dictionary<string, object> Tree { get; set; }
        public List<StateClass> StateClasses { get; set; }
        public Dictionary<string, Dictionary<string, string>> EnumValues { get; set; }
        public Dictionary<string, List<string>> StatesByOwner { get; set; }
    }

    static Derived Derive(Db db, string stateBase)
    {
        var d = new Derived();
        // subclasses: key = resolved Id, or "ext:BaseName" for bases outside the index
        var sub = new SortedDictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var t in db.Types.GroupBy(t => t.Id).Select(g => g.First()))
        {
            if (t.BaseName == null || t.Kind == "enum") continue;
            var key = t.BaseResolved ?? ("ext:" + t.BaseName);
            if (!sub.TryGetValue(key, out var l)) sub[key] = l = new();
            l.Add(t.Id);
        }
        foreach (var l in sub.Values) l.Sort(StringComparer.Ordinal);
        d.Subclasses = new Dictionary<string, List<string>>(sub);
        d.Roots = sub.Keys.Where(k => k.StartsWith("ext:") || !db.Canon.TryGetValue(k, out var c) || c.BaseResolved == null && c.BaseName == null).ToList();

        object Build(string id, int depth, HashSet<string> seen)
        {
            var node = new Dictionary<string, object>();
            if (depth > 25 || !seen.Add(id)) return node;
            if (sub.TryGetValue(id, out var kids))
                foreach (var k in kids) node[k] = Build(k, depth + 1, seen);
            seen.Remove(id);
            return node;
        }
        var tree = new Dictionary<string, object>();
        foreach (var r in d.Roots) tree[r] = Build(r, 0, new HashSet<string>());
        d.Tree = tree;

        // state classes: nested type whose ancestor chain reaches stateBase
        var states = new List<StateClass>();
        foreach (var t in db.Types)
        {
            if (t.Parent == null || t.Kind != "class") continue;
            var chain = new List<string>(); string cur = t.Id; string baseTxt = null; int guard = 0; bool hit = false;
            var rec = t;
            while (rec != null && guard++ < 30)
            {
                if (rec.BaseName == null) break;
                chain.Add(rec.Base);
                if (rec.BaseName == stateBase) { hit = true; baseTxt ??= rec.Base; break; }
                if (rec.BaseResolved != null && db.Canon.TryGetValue(rec.BaseResolved, out var b)) rec = b; else break;
            }
            if (!hit) continue;
            string og = null;
            var args = Db.Args(baseTxt);
            if (args.Count > 0) og = args[0];
            states.Add(new StateClass { Type = t.Id, Parent = t.Parent, StateBase = baseTxt, OwnerGeneric = og, Chain = chain, File = t.File, LineStart = t.LineStart, LineEnd = t.LineEnd });
        }
        d.StateClasses = states;
        d.StatesByOwner = states.GroupBy(s => s.Parent).OrderBy(g => g.Key, StringComparer.Ordinal).ToDictionary(g => g.Key, g => g.Select(s => s.Type).ToList());

        d.EnumValues = new Dictionary<string, Dictionary<string, string>>();
        foreach (var t in db.Types.Where(t => t.Kind == "enum" && t.Members != null))
        {
            var m = new Dictionary<string, string>();
            foreach (var e in t.Members) m[e.Name] = e.Value ?? ("?" + e.Raw);
            d.EnumValues[t.Id] = m;
        }
        return d;
    }
}

