        using (var w = new StreamWriter(jsonPath, false, new UTF8Encoding(false), 1 << 20))
        {
            w.Write("{\n\"meta\": " + JsonSerializer.Serialize(meta, jopt) + ",\n");
            WriteArr(w, "types", db.Types, jopt, false);
            WriteArr(w, "fields", db.Fields, jopt, false);
            WriteArr(w, "methods", db.Methods, jopt, false);
            WriteArr(w, "literals", literals, jopt, false);
            w.Write("\"derived\": " + JsonSerializer.Serialize(derived, jopt) + "\n}\n");
        }
        Log($"wrote {jsonPath} ({new FileInfo(jsonPath).Length / 1048576.0:F1} MB)");
        if (sqlite)
        {
            SqliteOut.Write(Path.Combine(outDir, "index.sqlite"), db, literals, derived);
            Log("wrote index.sqlite");
        }
        sw.Stop();
        Console.WriteLine($"OK files={files.Count} types={db.Types.Count} fields={db.Fields.Count} methods={db.Methods.Count} " +
            $"calls={stats["call_sites"]} literals={literals.Count} (num={stats["literals_num"]}, str={stats["literals_str"]}) " +
            $"state_classes={derived.StateClasses.Count} parse_error_files={errFiles.Count} failed={failed.Count} time={sw.Elapsed.TotalSeconds:F1}s");
        foreach (var f in failed.Take(10)) Console.Error.WriteLine("FAILED " + f);
        return 0;
    }

    static void WriteArr<T>(StreamWriter w, string name, List<T> items, JsonSerializerOptions o, bool last)
    {
        w.Write("\"" + name + "\": [\n");
        for (int i = 0; i < items.Count; i++)
        {
            w.Write(JsonSerializer.Serialize(items[i], o));
            w.Write(i < items.Count - 1 ? ",\n" : "\n");
        }
        w.Write(last ? "]\n" : "],\n");
    }

    // ============ derived ============
    public class StateClass
    {
        public string Type { get; set; }
        public string Parent { get; set; }
        public string StateBase { get; set; }
        public string OwnerGeneric { get; set; }
        public List<string> Chain { get; set; }
        public string File { get; set; }
        public int LineStart { get; set; }
        public int LineEnd { get; set; }
    }

    public class Derived
    {
        public List<string> Roots { get; set; }
        public Dictionary<string, List<string>> Subclasses { get; set; }
        public Dictionary<string, object> Tree { get; set; }
        public List<StateClass> StateClasses { get; set; }
        public Dictionary<string, Dictionary<string, string>> EnumValues { get; set; }
        public Dictionary<string, List<string>> StatesByOwner { get; set; }
    }

    static Derived Derive(Db db, string stateBase)
    {
        var d = new Derived();
        // subclasses: key = resolved Id, or "ext:BaseName" for bases outside the index
        var sub = new SortedDictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var t in db.Types.GroupBy(t => t.Id).Select(g => g.First()))
        {
            if (t.BaseName == null || t.Kind == "enum") continue;
            var key = t.BaseResolved ?? ("ext:" + t.BaseName);
            if (!sub.TryGetValue(key, out var l)) sub[key] = l = new();
            l.Add(t.Id);
        }
        foreach (var l in sub.Values) l.Sort(StringComparer.Ordinal);
        d.Subclasses = new Dictionary<string, List<string>>(sub);
        d.Roots = sub.Keys.Where(k => k.StartsWith("ext:") || !db.Canon.TryGetValue(k, out var c) || c.BaseResolved == null && c.BaseName == null).ToList();

        object Build(string id, int depth, HashSet<string> seen)
        {
            var node = new Dictionary<string, object>();
            if (depth > 25 || !seen.Add(id)) return node;
            if (sub.TryGetValue(id, out var kids))
                foreach (var k in kids) node[k] = Build(k, depth + 1, seen);
            seen.Remove(id);
            return node;
        }
        var tree = new Dictionary<string, object>();
        foreach (var r in d.Roots) tree[r] = Build(r, 0, new HashSet<string>());
        d.Tree = tree;

        // state classes: nested type whose ancestor chain reaches stateBase
        var states = new List<StateClass>();
        foreach (var t in db.Types)
        {
            if (t.Parent == null || t.Kind != "class") continue;
            var chain = new List<string>(); string cur = t.Id; string baseTxt = null; int guard = 0; bool hit = false;
            var rec = t;
            while (rec != null && guard++ < 30)
            {
                if (rec.BaseName == null) break;
                chain.Add(rec.Base);
                if (rec.BaseName == stateBase) { hit = true; baseTxt ??= rec.Base; break; }
                if (rec.BaseResolved != null && db.Canon.TryGetValue(rec.BaseResolved, out var b)) rec = b; else break;
            }
            if (!hit) continue;
            string og = null;
            var args = Db.Args(baseTxt);
            if (args.Count > 0) og = args[0];
            states.Add(new StateClass { Type = t.Id, Parent = t.Parent, StateBase = baseTxt, OwnerGeneric = og, Chain = chain, File = t.File, LineStart = t.LineStart, LineEnd = t.LineEnd });
        }
        d.StateClasses = states;
        d.StatesByOwner = states.GroupBy(s => s.Parent).OrderBy(g => g.Key, StringComparer.Ordinal).ToDictionary(g => g.Key, g => g.Select(s => s.Type).ToList());

        d.EnumValues = new Dictionary<string, Dictionary<string, string>>();
        foreach (var t in db.Types.Where(t => t.Kind == "enum" && t.Members != null))
        {
            var m = new Dictionary<string, string>();
            foreach (var e in t.Members) m[e.Name] = e.Value ?? ("?" + e.Raw);
            d.EnumValues[t.Id] = m;
        }
        return d;
    }
}

