using Microsoft.Data.Sqlite;

namespace CodeIndex;

public static class SqliteOut
{
    public static void Write(string path, Db db, List<LiteralRec> literals, Program.Derived derived)
    {
        SQLitePCL.Batteries_V2.Init();
        if (File.Exists(path)) File.Delete(path);
        using var cn = new SqliteConnection("Data Source=" + path);
        cn.Open();
        void Exec(string sql) { using var c = cn.CreateCommand(); c.CommandText = sql; c.ExecuteNonQuery(); }
        Exec(@"
PRAGMA journal_mode=OFF; PRAGMA synchronous=OFF;
CREATE TABLE types(id TEXT, name TEXT, kind TEXT, file TEXT, line_start INT, line_end INT, namespace TEXT, base TEXT, base_name TEXT, base_resolved TEXT, interfaces TEXT, parent TEXT, modifiers TEXT, attributes TEXT);
CREATE TABLE enum_members(enum_id TEXT, name TEXT, value TEXT, raw TEXT, line INT);
CREATE TABLE fields(owner TEXT, name TEXT, kind TEXT, type TEXT, is_static INT, is_const INT, is_readonly INT, initializer TEXT, init_expr TEXT, file TEXT, line INT);
CREATE TABLE methods(id INTEGER PRIMARY KEY, owner TEXT, name TEXT, kind TEXT, signature TEXT, modifiers TEXT, file TEXT, line_start INT, line_end INT, is_override INT, override_of TEXT);
CREATE TABLE calls(method_id INT, name TEXT, receiver TEXT, receiver_type TEXT, line INT, count INT);
CREATE TABLE literals(kind TEXT, value TEXT, num REAL, text TEXT, owner_type TEXT, owner TEXT, owner_kind TEXT, file TEXT, line INT, expr TEXT, context TEXT);
CREATE TABLE state_classes(type TEXT, parent TEXT, state_base TEXT, owner_generic TEXT, file TEXT, line_start INT, line_end INT);
");
        using var tx = cn.BeginTransaction();
        void Insert(string sql, Action<SqliteCommand> fill, IEnumerable<Action<SqliteCommand>> rows)
        {
            using var c = cn.CreateCommand(); c.Transaction = tx; c.CommandText = sql;
            foreach (var r in rows) { c.Parameters.Clear(); r(c); c.ExecuteNonQuery(); }
        }
        static void P(SqliteCommand c, string n, object v) => c.Parameters.AddWithValue(n, v ?? DBNull.Value);

        Insert("INSERT INTO types VALUES($a,$b,$c,$d,$e,$f,$g,$h,$i,$j,$k,$l,$m,$n)", null,
            db.Types.Select<TypeRec, Action<SqliteCommand>>(t => c =>
            {
                P(c, "$a", t.Id); P(c, "$b", t.Name); P(c, "$c", t.Kind); P(c, "$d", t.File); P(c, "$e", t.LineStart); P(c, "$f", t.LineEnd);
                P(c, "$g", t.Namespace); P(c, "$h", t.Base); P(c, "$i", t.BaseName); P(c, "$j", t.BaseResolved);
                P(c, "$k", t.Interfaces == null ? null : string.Join(", ", t.Interfaces)); P(c, "$l", t.Parent);
                P(c, "$m", t.Modifiers == null ? null : string.Join(" ", t.Modifiers)); P(c, "$n", t.Attributes == null ? null : string.Join("; ", t.Attributes));
            }));
        Insert("INSERT INTO enum_members VALUES($a,$b,$c,$d,$e)", null,
            db.Types.Where(t => t.Members != null).SelectMany(t => t.Members.Select<EnumMemberRec, Action<SqliteCommand>>(m => c =>
            { P(c, "$a", t.Id); P(c, "$b", m.Name); P(c, "$c", m.Value); P(c, "$d", m.Raw); P(c, "$e", m.Line); })));
        Insert("INSERT INTO fields VALUES($a,$b,$c,$d,$e,$f,$g,$h,$i,$j,$k)", null,
            db.Fields.Select<FieldRec, Action<SqliteCommand>>(f => c =>
            {
                P(c, "$a", f.Owner); P(c, "$b", f.Name); P(c, "$c", f.Kind); P(c, "$d", f.Type); P(c, "$e", f.Static ? 1 : 0); P(c, "$f", f.Const ? 1 : 0);
                P(c, "$g", f.Readonly ? 1 : 0); P(c, "$h", f.Initializer); P(c, "$i", f.InitExpr); P(c, "$j", f.File); P(c, "$k", f.Line);
            }));
        int id = 0;
        var mids = new Dictionary<MethodRec, int>();
        foreach (var m in db.Methods) mids[m] = ++id;
        Insert("INSERT INTO methods VALUES($a,$b,$c,$d,$e,$f,$g,$h,$i,$j,$k)", null,
            db.Methods.Select<MethodRec, Action<SqliteCommand>>(m => c =>
            {
                P(c, "$a", mids[m]); P(c, "$b", m.Owner); P(c, "$c", m.Name); P(c, "$d", m.Kind); P(c, "$e", m.Signature);
                P(c, "$f", m.Modifiers == null ? null : string.Join(" ", m.Modifiers)); P(c, "$g", m.File); P(c, "$h", m.LineStart); P(c, "$i", m.LineEnd);
                P(c, "$j", m.Override ? 1 : 0); P(c, "$k", m.OverrideOf);
            }));
        Insert("INSERT INTO calls VALUES($a,$b,$c,$d,$e,$f)", null,
            db.Methods.Where(m => m.Calls != null).SelectMany(m => m.Calls.Select<CallRec, Action<SqliteCommand>>(k => c =>
            { P(c, "$a", mids[m]); P(c, "$b", k.Name); P(c, "$c", k.Receiver); P(c, "$d", k.ReceiverType); P(c, "$e", k.Line); P(c, "$f", k.Count); })));
        Insert("INSERT INTO literals VALUES($a,$b,$c,$d,$e,$f,$g,$h,$i,$j,$k)", null,
            literals.Select<LiteralRec, Action<SqliteCommand>>(l => c =>
            {
                P(c, "$a", l.Kind); P(c, "$b", l.Value);
                P(c, "$c", l.Kind == "num" && double.TryParse(l.Value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var dv) ? dv : null);
                P(c, "$d", l.Text); P(c, "$e", l.OwnerType); P(c, "$f", l.Owner); P(c, "$g", l.OwnerKind); P(c, "$h", l.File); P(c, "$i", l.Line); P(c, "$j", l.Expr); P(c, "$k", l.Context);
            }));
        Insert("INSERT INTO state_classes VALUES($a,$b,$c,$d,$e,$f,$g)", null,
            derived.StateClasses.Select<Program.StateClass, Action<SqliteCommand>>(s => c =>
            { P(c, "$a", s.Type); P(c, "$b", s.Parent); P(c, "$c", s.StateBase); P(c, "$d", s.OwnerGeneric); P(c, "$e", s.File); P(c, "$f", s.LineStart); P(c, "$g", s.LineEnd); }));
        tx.Commit();
        Exec(@"CREATE INDEX i_types_base ON types(base_name); CREATE INDEX i_types_id ON types(id);
CREATE INDEX i_lit_num ON literals(num); CREATE INDEX i_lit_owner ON literals(owner_type, owner);
CREATE INDEX i_calls_name ON calls(name); CREATE INDEX i_calls_m ON calls(method_id);
CREATE INDEX i_methods_owner ON methods(owner, name); CREATE INDEX i_fields_owner ON fields(owner, name);");
    }
}

