#!/usr/bin/env python3
"""q.py - запросы к index.json, который строит codeindex.

Примеры:
  python q.py --index ../../wol-ref/index/index.json types --base Enemy
  python q.py literals --type Player --method RunState.Update
  python q.py callers Player.GetInputVector
  python q.py find-number 0.125
  python q.py --json find-number 9 > out.json

Индекс ищется: --index, переменная окружения CODEINDEX, ./index.json, ./index/index.json.
"""
import argparse
import json
import math
import os
import sys
from collections import defaultdict


def find_index(arg):
    cands = [arg, os.environ.get("CODEINDEX"), "index.json", os.path.join("index", "index.json")]
    for c in cands:
        if c and os.path.isfile(c):
            return c
    sys.exit("index.json не найден: укажите --index или переменную CODEINDEX")


class Index:
    def __init__(self, path):
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
        self.meta = d["meta"]
        self.types = d["types"]
        self.fields = d["fields"]
        self.methods = d["methods"]
        self.literals = d["literals"]
        self.derived = d["derived"]
        self.by_id = {}
        self.by_name = defaultdict(list)
        for t in self.types:
            self.by_id.setdefault(t["id"], t)
            self.by_name[t["name"]].append(t)
        self.subs = self.derived["subclasses"]

    # ---- типы ----
    def resolve_types(self, s):
        """'Player' / 'Player.RunState' -> список id (точное совпадение id или простого имени)."""
        if s in self.by_id:
            return [s]
        ids = sorted({t["id"] for t in self.by_name.get(s, [])})
        if not ids:
            ids = sorted({t["id"] for t in self.types if t["id"].endswith("." + s)})
        return ids

    def descendants(self, ids, include_self=False):
        out, stack, seen = [], list(ids), set()
        keys = set(ids)
        # внешние базы: ключ 'ext:Имя'
        for i in ids:
            keys.add("ext:" + i.split(".")[-1])
        stack = list(keys)
        while stack:
            k = stack.pop()
            for c in self.subs.get(k, []):
                if c not in seen:
                    seen.add(c)
                    out.append(c)
                    stack.append(c)
        if include_self:
            out = list(ids) + out
        return sorted(set(out))

    def ancestors(self, tid):
        out, cur, guard = [], self.by_id.get(tid), 0
        while cur and guard < 40:
            guard += 1
            b = cur.get("base_resolved")
            if b and b in self.by_id:
                out.append(b)
                cur = self.by_id[b]
            else:
                if cur.get("base_name"):
                    out.append("ext:" + cur["base_name"])
                break
        return out


def type_match(owner_type, spec, nested=True):
    """owner_type (Id) подходит под spec (Id или простое имя, вложенные включаются)."""
    if owner_type is None:
        return False
    if owner_type == spec or owner_type.endswith("." + spec) and "." not in spec:
        return True
    if nested:
        return owner_type.startswith(spec + ".") or ("." + spec + ".") in owner_type
    return False


def emit(args, rows, fmt):
    if args.json:
        json.dump(rows, sys.stdout, ensure_ascii=False, indent=1)
        print()
        return
    for r in rows:
        print(fmt(r))
    print(f"-- {len(rows)} rows", file=sys.stderr)


def cmd_types(ix, a):
    rows = []
    ids = None
    if a.base:
        bids = ix.resolve_types(a.base)
        if a.direct:
            ids = set()
            for b in bids or [a.base]:
                ids.update(ix.subs.get(b, []))
                ids.update(ix.subs.get("ext:" + b, []))
        else:
            ids = set(ix.descendants(bids or [a.base]))
        if not bids and not any(("ext:" + a.base) in ix.subs for _ in [0]):
            print(f"тип {a.base!r} не найден в индексе", file=sys.stderr)
    for t in ix.types:
        if ids is not None and t["id"] not in ids:
            continue
        if a.kind and t["kind"] != a.kind:
            continue
        if a.name and a.name.lower() not in t["name"].lower():
            continue
        if a.parent and t.get("parent") != a.parent and not (t.get("parent") or "").endswith("." + a.parent):
            continue
        rows.append(t)
    emit(a, rows, lambda t: f'{t["id"]:50s} {t["kind"]:9s} : {t.get("base","") or ""}  [{t["file"]}:{t["line_start"]}-{t["line_end"]}]')


def cmd_literals(ix, a):
    rows = []
    for l in ix.literals:
        if a.kind and l["kind"] != a.kind:
            continue
        if a.type and not type_match(l["owner_type"], a.type, not a.exact):
            continue
        if a.method and not (l["owner"] == a.method or l["owner"].split(".")[-1] == a.method or l["owner"].startswith(a.method + ".")):
            continue
        if a.file and l["file"] != a.file:
            continue
        if a.value is not None:
            try:
                if not (l["kind"] == "num" and close(float(l["value"]), a.value, a.tol)):
                    continue
            except ValueError:
                continue
        if a.context and a.context.lower() not in (l.get("context") or "").lower():
            continue
        rows.append(l)
    emit(a, rows, lambda l: f'{l["file"]}:{l["line"]:<6} {l["owner_type"] or "":32s} {l["owner"]:28s} {l["value"]:>10s}  {l.get("context","")}   | {l["expr"]}')


def close(x, y, tol):
    return abs(x - y) <= max(tol, 0) + 1e-12 * max(1.0, abs(y))


def cmd_find_number(ix, a):
    a.kind = "num"
    a.type = a.method = a.file = a.context = None
    a.exact = False
    a.value = a.number
    cmd_literals(ix, a)


def split_target(t):
    if "." in t:
        ty, m = t.rsplit(".", 1)
    else:
        ty, m = None, t
    if m in ("ctor", "new"):
        m = ".ctor"
    return ty, m


def cmd_callers(ix, a):
    ty, name = split_target(a.target)
    rel_exact, rel_desc, rel_anc = set(), set(), set()
    if ty:
        ids = ix.resolve_types(ty) or []
        simple = {i.split(".")[-1] for i in ids} | {ty.split(".")[-1]}
        rel_exact = simple
        rel_desc = {i.split(".")[-1] for i in ix.descendants(ids)}
        anc = set()
        for i in ids:
            anc.update(x.replace("ext:", "").split(".")[-1] for x in ix.ancestors(i))
        rel_anc = anc
    rows = []
    for m in ix.methods:
        for c in m.get("calls") or []:
            if c["name"] != name:
                continue
            rt = c.get("receiver_type")
            if ty is None:
                conf = "name"
            elif rt is None:
                conf = "unknown"
            elif rt in rel_exact:
                conf = "exact"
            elif rt in rel_desc:
                conf = "via-subclass"
            elif rt in rel_anc:
                conf = "via-base"
            else:
                continue
            if a.min_conf == "exact" and conf not in ("exact", "name"):
                continue
            if a.min_conf == "typed" and conf == "unknown":
                continue
            rows.append({"caller": f'{m["owner"]}.{m["name"]}', "file": m["file"], "line": c["line"], "count": c.get("count", 1),
                         "receiver": c.get("receiver"), "receiver_type": rt, "confidence": conf})
    order = {"exact": 0, "name": 0, "via-subclass": 1, "via-base": 1, "unknown": 2}
    rows.sort(key=lambda r: (order[r["confidence"]], r["file"], r["line"]))
    emit(a, rows, lambda r: f'{r["confidence"]:12s} {r["file"]}:{r["line"]:<6} {r["caller"]:50s} {(r["receiver"] or "(this)")}.{name}  x{r["count"]}')


def cmd_callees(ix, a):
    ty, name = split_target(a.target)
    rows = []
    for m in ix.methods:
        if m["name"] != name:
            continue
        if ty and not type_match(m["owner"], ty, False) and m["owner"].split(".")[-1] != ty.split(".")[-1]:
            continue
        for c in m.get("calls") or []:
            rows.append({"method": f'{m["owner"]}.{m["name"]}', "file": m["file"], "line": c["line"], "callee": c["name"],
                         "receiver": c.get("receiver"), "receiver_type": c.get("receiver_type"), "count": c.get("count", 1)})
    emit(a, rows, lambda r: f'{r["file"]}:{r["line"]:<6} {r["method"]:40s} -> {(r["receiver_type"] or "?")}.{r["callee"]}  ({r["receiver"] or "this"}) x{r["count"]}')


def cmd_methods(ix, a):
    rows = [m for m in ix.methods
            if (not a.type or type_match(m["owner"], a.type, not a.exact))
            and (not a.name or a.name.lower() in m["name"].lower())
            and (not a.overrides or m.get("override"))]
    emit(a, rows, lambda m: f'{m["file"]}:{m["line_start"]}-{m["line_end"]:<6} {m["owner"]}.{m["signature"]}' + (f'  [overrides {m["override_of"]}]' if m.get("override_of") else ""))


def cmd_fields(ix, a):
    rows = [f for f in ix.fields
            if (not a.type or type_match(f["owner"], a.type, not a.exact))
            and (not a.name or a.name.lower() in f["name"].lower())
            and (not a.const or f.get("const"))
            and (not a.with_init or f.get("initializer") is not None)]
    emit(a, rows, lambda f: f'{f["file"]}:{f["line"]:<6} {f["owner"]}.{f["name"]}: {f["type"]}' + (f' = {f["initializer"]}' if f.get("initializer") is not None else (f' = {f["init_expr"]}' if f.get("init_expr") else "")))


def cmd_enum(ix, a):
    rows = []
    for t in ix.types:
        if t["kind"] == "enum" and (t["id"] == a.name or t["name"] == a.name):
            rows.append({"enum": t["id"], "members": t.get("members", [])})
    emit(a, rows, lambda r: r["enum"] + ": " + ", ".join(f'{m["name"]}={m.get("value", "?")}' for m in r["members"]))


def cmd_states(ix, a):
    rows = [s for s in ix.derived["state_classes"] if not a.owner or s["parent"] == a.owner or s["parent"].endswith("." + a.owner)]
    emit(a, rows, lambda s: f'{s["type"]:50s} owner<{s.get("owner_generic")}> chain={" > ".join(s["chain"])}  [{s["file"]}:{s["line_start"]}-{s["line_end"]}]')


def cmd_tree(ix, a):
    ids = ix.resolve_types(a.type) or [a.type]
    def build(k, d, seen):
        if d > 30 or k in seen:
            return {}
        seen = seen | {k}
        return {c: build(c, d + 1, seen) for c in ix.subs.get(k, [])}
    tree = {i: build(i, 0, set()) for i in ids}
    if a.json:
        json.dump(tree, sys.stdout, ensure_ascii=False, indent=1)
        print()
        return
    def pr(n, ind):
        for k, v in n.items():
            print("  " * ind + k)
            pr(v, ind + 1)
    pr(tree, 0)


def cmd_stats(ix, a):
    emit(a, [ix.meta["stats"]], lambda r: json.dumps(r, ensure_ascii=False, indent=1))


def main():
    ap = argparse.ArgumentParser(description="Запросы к index.json (codeindex)")
    ap.add_argument("--index", help="путь к index.json")
    ap.add_argument("--json", action="store_true", help="вывод JSON вместо текста")
    sp = ap.add_subparsers(dest="cmd", required=True)

    p = sp.add_parser("types", help="типы; --base X = все потомки X")
    p.add_argument("--base"); p.add_argument("--direct", action="store_true", help="только прямые потомки")
    p.add_argument("--kind"); p.add_argument("--name", help="подстрока имени"); p.add_argument("--parent", help="вложенные в этот тип")
    p.set_defaults(f=cmd_types)

    p = sp.add_parser("literals", help="литералы")
    p.add_argument("--type"); p.add_argument("--method", help="метод / поле / Prop.get"); p.add_argument("--exact", action="store_true", help="без вложенных типов")
    p.add_argument("--kind", choices=["num", "str"]); p.add_argument("--file"); p.add_argument("--context", help="подстрока контекста")
    p.add_argument("--value", type=float); p.add_argument("--tol", type=float, default=0.0)
    p.set_defaults(f=cmd_literals)

    p = sp.add_parser("find-number", help="где в коде встречается число")
    p.add_argument("number", type=float); p.add_argument("--tol", type=float, default=1e-9)
    p.set_defaults(f=cmd_find_number)

    p = sp.add_parser("callers", help="кто вызывает Type.Method (или просто Method; Type.ctor)")
    p.add_argument("target"); p.add_argument("--min-conf", choices=["any", "typed", "exact"], default="any")
    p.set_defaults(f=cmd_callers)

    p = sp.add_parser("callees", help="что вызывает Type.Method")
    p.add_argument("target"); p.set_defaults(f=cmd_callees)

    p = sp.add_parser("methods"); p.add_argument("--type"); p.add_argument("--name"); p.add_argument("--exact", action="store_true"); p.add_argument("--overrides", action="store_true")
    p.set_defaults(f=cmd_methods)

    p = sp.add_parser("fields"); p.add_argument("--type"); p.add_argument("--name"); p.add_argument("--exact", action="store_true")
    p.add_argument("--const", action="store_true"); p.add_argument("--with-init", action="store_true")
    p.set_defaults(f=cmd_fields)

    p = sp.add_parser("enum"); p.add_argument("name"); p.set_defaults(f=cmd_enum)
    p = sp.add_parser("states", help="классы-состояния FSM"); p.add_argument("--owner"); p.set_defaults(f=cmd_states)
    p = sp.add_parser("tree", help="дерево наследования"); p.add_argument("type"); p.set_defaults(f=cmd_tree)
    p = sp.add_parser("stats"); p.set_defaults(f=cmd_stats)

    a = ap.parse_args()
    ix = Index(find_index(a.index))
    a.f(ix, a)


if __name__ == "__main__":
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    main()

