#!/usr/bin/env python3
"""q.py - запросы к index.json, который строит codeindex.

Примеры:
  python q.py --index ../../wol-ref/index/index.json types --base Enemy
  python q.py literals --type Player --method RunState.Update
  python q.py callers Player.GetInputVector
  python q.py find-number 0.125
  python q.py --json find-number 9 > out.json

Индекс ищется: --index, переменная окружения CODEINDEX, ./index.json, ./index/index.json.
"""
import argparse
import json
import math
import os
import sys
from collections import defaultdict


def find_index(arg):
    cands = [arg, os.environ.get("CODEINDEX"), "index.json", os.path.join("index", "index.json")]
    for c in cands:
        if c and os.path.isfile(c):
            return c
    sys.exit("index.json не найден: укажите --index или переменную CODEINDEX")


class Index:
    def __init__(self, path):
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
        self.meta = d["meta"]
        self.types = d["types"]
        self.fields = d["fields"]
        self.methods = d["methods"]
        self.literals = d["literals"]
        self.derived = d["derived"]
        self.by_id = {}
        self.by_name = defaultdict(list)
        for t in self.types:
            self.by_id.setdefault(t["id"], t)
            self.by_name[t["name"]].append(t)
        self.subs = self.derived["subclasses"]

    # ---- типы ----
    def resolve_types(self, s):
        """'Player' / 'Player.RunState' -> список id (точное совпадение id или простого имени)."""
        if s in self.by_id:
            return [s]
        ids = sorted({t["id"] for t in self.by_name.get(s, [])})
        if not ids:
            ids = sorted({t["id"] for t in self.types if t["id"].endswith("." + s)})
        return ids

    def descendants(self, ids, include_self=False):
        out, stack, seen = [], list(ids), set()
        keys = set(ids)
        # внешние базы: ключ 'ext:Имя'
        for i in ids:
            keys.add("ext:" + i.split(".")[-1])
        stack = list(keys)
        while stack:
            k = stack.pop()
            for c in self.subs.get(k, []):
                if c not in seen:
                    seen.add(c)
                    out.append(c)
                    stack.append(c)
        if include_self:
            out = list(ids) + out
        return sorted(set(out))

    def ancestors(self, tid):
        out, cur, guard = [], self.by_id.get(tid), 0
        while cur and guard < 40:
            guard += 1
            b = cur.get("base_resolved")
            if b and b in self.by_id:
                out.append(b)
                cur = self.by_id[b]
            else:
                if cur.get("base_name"):
                    out.append("ext:" + cur["base_name"])
                break
        return out


def type_match(owner_type, spec, nested=True):
    """owner_type (Id) подходит под spec (Id или простое имя, вложенные включаются)."""
    if owner_type is None:
        return False
    if owner_type == spec or owner_type.endswith("." + spec) and "." not in spec:
        return True
    if nested:
        return owner_type.startswith(spec + ".") or ("." + spec + ".") in owner_type
    return False


def emit(args, rows, fmt):
    if args.json:
        json.dump(rows, sys.stdout, ensure_ascii=False, indent=1)
        print()
        return
    for r in rows:
        print(fmt(r))
    print(f"-- {len(rows)} rows", file=sys.stderr)


def cmd_types(ix, a):
