    emit(a, rows, lambda r: r["enum"] + ": " + ", ".join(f'{m["name"]}={m.get("value", "?")}' for m in r["members"]))


def cmd_states(ix, a):
    rows = [s for s in ix.derived["state_classes"] if not a.owner or s["parent"] == a.owner or s["parent"].endswith("." + a.owner)]
    emit(a, rows, lambda s: f'{s["type"]:50s} owner<{s.get("owner_generic")}> chain={" > ".join(s["chain"])}  [{s["file"]}:{s["line_start"]}-{s["line_end"]}]')


def cmd_tree(ix, a):
    ids = ix.resolve_types(a.type) or [a.type]
    def build(k, d, seen):
        if d > 30 or k in seen:
            return {}
        seen = seen | {k}
        return {c: build(c, d + 1, seen) for c in ix.subs.get(k, [])}
    tree = {i: build(i, 0, set()) for i in ids}
    if a.json:
        json.dump(tree, sys.stdout, ensure_ascii=False, indent=1)
        print()
        return
    def pr(n, ind):
        for k, v in n.items():
            print("  " * ind + k)
            pr(v, ind + 1)
    pr(tree, 0)


def cmd_stats(ix, a):
    emit(a, [ix.meta["stats"]], lambda r: json.dumps(r, ensure_ascii=False, indent=1))


def main():
    ap = argparse.ArgumentParser(description="Запросы к index.json (codeindex)")
    ap.add_argument("--index", help="путь к index.json")
    ap.add_argument("--json", action="store_true", help="вывод JSON вместо текста")
    sp = ap.add_subparsers(dest="cmd", required=True)

    p = sp.add_parser("types", help="типы; --base X = все потомки X")
    p.add_argument("--base"); p.add_argument("--direct", action="store_true", help="только прямые потомки")
    p.add_argument("--kind"); p.add_argument("--name", help="подстрока имени"); p.add_argument("--parent", help="вложенные в этот тип")
    p.set_defaults(f=cmd_types)

    p = sp.add_parser("literals", help="литералы")
    p.add_argument("--type"); p.add_argument("--method", help="метод / поле / Prop.get"); p.add_argument("--exact", action="store_true", help="без вложенных типов")
    p.add_argument("--kind", choices=["num", "str"]); p.add_argument("--file"); p.add_argument("--context", help="подстрока контекста")
    p.add_argument("--value", type=float); p.add_argument("--tol", type=float, default=0.0)
    p.set_defaults(f=cmd_literals)

    p = sp.add_parser("find-number", help="где в коде встречается число")
    p.add_argument("number", type=float); p.add_argument("--tol", type=float, default=1e-9)
    p.set_defaults(f=cmd_find_number)

    p = sp.add_parser("callers", help="кто вызывает Type.Method (или просто Method; Type.ctor)")
    p.add_argument("target"); p.add_argument("--min-conf", choices=["any", "typed", "exact"], default="any")
    p.set_defaults(f=cmd_callers)

    p = sp.add_parser("callees", help="что вызывает Type.Method")
    p.add_argument("target"); p.set_defaults(f=cmd_callees)

    p = sp.add_parser("methods"); p.add_argument("--type"); p.add_argument("--name"); p.add_argument("--exact", action="store_true"); p.add_argument("--overrides", action="store_true")
    p.set_defaults(f=cmd_methods)

    p = sp.add_parser("fields"); p.add_argument("--type"); p.add_argument("--name"); p.add_argument("--exact", action="store_true")
    p.add_argument("--const", action="store_true"); p.add_argument("--with-init", action="store_true")
    p.set_defaults(f=cmd_fields)

    p = sp.add_parser("enum"); p.add_argument("name"); p.set_defaults(f=cmd_enum)
    p = sp.add_parser("states", help="классы-состояния FSM"); p.add_argument("--owner"); p.set_defaults(f=cmd_states)
    p = sp.add_parser("tree", help="дерево наследования"); p.add_argument("type"); p.set_defaults(f=cmd_tree)
    p = sp.add_parser("stats"); p.set_defaults(f=cmd_stats)

    a = ap.parse_args()
    ix = Index(find_index(a.index))
    a.f(ix, a)


if __name__ == "__main__":
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    main()

