#!/usr/bin/env python3
"""verify_numbers.py - эвристическая сверка чисел в спеках с кодом (index.json) и данными.

    python verify_numbers.py --spec <dir> --index <index.json> --data <data_dir> [--out-dir DIR]

Для каждого .md в --spec ищет утверждения с числами и ссылки «Источник: ...»,
проверяет, что число встречается как литерал в указанном методе/типе/файле
(через index.json от codeindex) либо как значение в указанном JSON/CSV.
Спеки только читаются. Это ЭВРИСТИКА - см. README.md (ограничения).
"""
import argparse
import bisect
import csv
import fnmatch
import json
import os
import re
import sys
import time
from collections import defaultdict

# ----------------------------------------------------------------------------
# числа в тексте
# ----------------------------------------------------------------------------
NUM_RE = re.compile(r'(?:(?<![\w.)\]])([-−])(?=\d))?(?<![\w.])(\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)([A-Za-zА-я°%×]*)')
OK_SUFFIX = {"", "%", "с", "сек", "м", "мс", "f", "F", "x", "×", "s", "ms", "m", "px", "°",
             "Гц", "Hz", "hp", "HP", "х"}
UNIT_AFTER = re.compile(r'^\s?(?:с(?![\w])|сек|м/с|м(?![\w])|мс|%|×|px|HP|ХП|Гц|тик\w*|кадр\w*|'
                        r'раз(?![\w])|ед\.?|шт|градус\w*|°|клет\w*|пикс\w*|оч\w*|урон\w*|секунд\w*|метр\w*)')

STRIP_RES = [
    re.compile(r'https?://\S+'),
    re.compile(r'[\w/.*\-]+\.(?:cs|json|csv|md|prefab|asset|py|toml|png|wav|ogg)\b'),
    re.compile(r'\b\d{2}[a-z]?-[A-Za-z][\w-]*'),                      # 00-core, 05b-arcana
    re.compile(r'№\s*\d+[a-z]?'),                                  # №12
    re.compile(r'\b(?:п|пп)\.\s*\d+(?:[.,–-]\d+)*'),                    # п. 9
    re.compile(r'(?i)\b(?:пункт\w*|раздел\w*|табл\w*|срез\w*|стади\w*|фаз\w*|шаг\w*|глав\w*|ревизи\w*|версия|тир)\s+(?:\w+\s+)?\d+'),
    re.compile(r'(?<![\w.])#\d+'),
]

ENUM_ITEM = re.compile(r'^\s*(?:\d+[.)]|[-*+])\s+')
HEADING = re.compile(r'^(#{1,6})\s+(.*)$')
SRC_LINE = re.compile(r'^\s*(?:[-*>+]\s*)?(?:\*\*|__)?\s*Источни(?:к|ки|ков)\s*(?:\*\*|__)?\s*[:：]')
SRC_INLINE = re.compile(r'Источни(?:к|ки|ков)(?:\*\*|__)?\s*[:：]')
SRC_HEADING = re.compile(r'^Источни')


def parse_args():
    ap = argparse.ArgumentParser(description="Сверка чисел спеков с кодом (index.json) и данными")
    ap.add_argument("--spec", required=True, help="папка со спеками (.md), только чтение")
    ap.add_argument("--index", required=True, help="index.json от codeindex")
    ap.add_argument("--data", required=True, help="папка с данными (JSON/CSV)")
    ap.add_argument("--out-dir", default="verify-out", help="куда писать verify-auto.md/.json")
    ap.add_argument("--out-md", help="полный путь markdown-отчёта (перекрывает --out-dir)")
    ap.add_argument("--out-json", help="полный путь JSON-отчёта (перекрывает --out-dir)")
    ap.add_argument("--tol", type=float, default=1e-4, help="абсолютный допуск сравнения (1e-4)")
    ap.add_argument("--factors", default="2,10,60,100,120,1000", help="множители для производных форм ×N / ÷N")
    ap.add_argument("--no-derived", action="store_true", help="только точные совпадения")
    ap.add_argument("--no-pairs", action="store_true", help="не искать произведения/частные пар литералов")
    ap.add_argument("--entity-exclude", default="dialog,speakers,tilemaps,tilesets,fonts,ui,export",
                    help="подпапки/префиксы data, не сканируемые как сущности")
    ap.add_argument("--max-notfound", type=int, default=60, help="сколько NOT_FOUND на файл в markdown")
    ap.add_argument("--top", type=int, default=20, help="размер общего топа NOT_FOUND")
    ap.add_argument("--dump-claims", action="store_true", help="класть в JSON все утверждения, не только NOT_FOUND")
    ap.add_argument("--include", help="маска файлов спеки (fnmatch), напр. '0[1-4]*.md'")
    return ap.parse_args()


# ----------------------------------------------------------------------------
# области поиска значений
# ----------------------------------------------------------------------------
class Scope:
    __slots__ = ("label", "kind", "vals", "n", "small")

    def __init__(self, label, kind, values):
        self.label = label
        self.kind = kind          # method | type | file | data-file | data-entity
        self.vals = sorted(set(values))
        self.n = len(self.vals)
        self.small = [v for v in self.vals if v not in (0.0, 1.0, -1.0)]

    def has(self, v, tol):
        i = bisect.bisect_left(self.vals, v - tol)
        return i < self.n and self.vals[i] <= v + tol

    def pair(self, v, tol):
        """v == a*b  или  v == a/b  для литералов a, b области (малые области)."""
        s = self.small
        if len(s) > 260 or not s:
            return None
        for a in s:
            for target, how in ((v / a, "*"), (v * a, "/")):
                if self.has(target, tol / max(abs(a), 1.0) if how == "*" else tol * max(abs(a), 1.0)) and target not in (0.0, 1.0, -1.0):
                    return f"{a:g} {how} {target:g}"
        return None


class CodeIndex:
    def __init__(self, path):
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
        self.meta = d["meta"]
        self.lits = []           # (value, file, owner_type, owner, line)
        self.by_type = defaultdict(list)
        self.by_member = defaultdict(list)
        self.by_file = defaultdict(list)
        self.type_ids = set()
        self.types_by_name = defaultdict(set)
        self.files_by_base = defaultdict(set)
        for t in d["types"]:
            self.type_ids.add(t["id"])
            self.types_by_name[t["name"]].add(t["id"])
        for l in d["literals"]:
            if l["kind"] != "num":
                continue
            try:
                v = float(l["value"])
            except ValueError:
                continue
            i = len(self.lits)
            self.lits.append((v, l["file"], l["owner_type"], l["owner"], l["line"]))
            self.by_type[l["owner_type"]].append(i)
            self.by_member[(l["owner_type"], l["owner"])].append(i)
            self.by_file[l["file"]].append(i)
        for f in self.by_file:
            self.files_by_base[os.path.basename(f).lower()].add(f)
        for t in d["types"]:
            self.files_by_base[os.path.basename(t["file"]).lower()].add(t["file"])
        self.sorted_ids = sorted(self.type_ids)
        self.global_vals = sorted((l[0], k) for k, l in enumerate(self.lits))
        self.gv = [x[0] for x in self.global_vals]

    def files_matching(self, pat):
        pat = pat.lower()
        if "*" in pat or "?" in pat:
            return sorted({f for b, fs in self.files_by_base.items() if fnmatch.fnmatch(b, pat) for f in fs})
        return sorted(self.files_by_base.get(pat, ()))

    def type_family(self, tid):
        """tid + все вложенные типы."""
        out = [tid]
        i = bisect.bisect_left(self.sorted_ids, tid + ".")
        while i < len(self.sorted_ids) and self.sorted_ids[i].startswith(tid + "."):
            out.append(self.sorted_ids[i])
            i += 1
        return out

    def scope_from(self, idxs, label, kind):
        return Scope(label, kind, [self.lits[i][0] for i in idxs])

    def types_named(self, name, files=None):
        ids = set()
        for tid in self.types_by_name.get(name.split(".")[-1], ()):
            if tid == name or tid.endswith("." + name) or "." not in name:
                ids.add(tid)
        if files is not None:
            fset = set(files)
            filt = {t for t in ids if any(self.lits[i][1] in fset for i in self.by_type.get(t, [])[:1]) or self._type_in_files(t, fset)}
            if filt:
                return filt
        return ids

    def _type_in_files(self, tid, fset):
        for i in self.by_type.get(tid, ()):
            if self.lits[i][1] in fset:
                return True
        return False

    def member_scopes(self, name, files):
        """name = 'Method' | 'Type' | 'Type.Member'. Возвращает (scopes, found_in_files)."""
        fset = set(files) if files else None
        res = []
        parts = name.split(".")
        if len(parts) >= 2:
            tname, mname = ".".join(parts[:-1]), parts[-1]
            idxs = []
            for tid in self.types_named(tname, files):
                for (ot, ow), lst in self.by_member.items() if False else []:
                    pass
            for tid in self.types_named(tname, None):
                for fam in self.type_family(tid):
                    for (ot, ow) in [(fam, mname)]:
                        idxs += self.by_member.get((ot, ow), [])
                    idxs += self.by_member.get((fam, mname + ".get"), []) + self.by_member.get((fam, mname + ".set"), [])
            if idxs:
                res.append(self.scope_from(idxs, name, "method"))
            # Type.NestedType
            for tid in self.types_named(parts[-1], None):
                if tid.endswith("." + name) or tid == name:
                    idxs2 = [i for fam in self.type_family(tid) for i in self.by_type.get(fam, [])]
                    if idxs2:
                        res.append(self.scope_from(idxs2, name, "type"))
            return res
        # простое имя: тип(ы)
        tids = self.types_named(name, files)
        idxs = [i for tid in tids for fam in self.type_family(tid) for i in self.by_type.get(fam, [])]
        if idxs:
            res.append(self.scope_from(idxs, name, "type"))
        # метод/поле с таким именем (в файлах, иначе везде)
        idxm = []
        for (ot, ow), lst in self.member_index().get(name, {}).items():
            for i in lst:
                if fset is None or self.lits[i][1] in fset:
                    idxm.append(i)
        if not idxm and fset is not None:
            for (ot, ow), lst in self.member_index().get(name, {}).items():
                idxm += lst
        if idxm:
            res.append(self.scope_from(idxm, name, "method"))
        return res

    _midx = None

    def member_index(self):
        if self._midx is None:
            m = defaultdict(dict)
            for (ot, ow), lst in self.by_member.items():
                base = ow.split(".")[0]
                m[base][(ot, ow)] = lst
            self._midx = m
        return self._midx

    def where(self, v, tol, prefer_files=(), limit=3):
        lo = bisect.bisect_left(self.gv, v - tol)
        hits = []
        while lo < len(self.gv) and self.gv[lo] <= v + tol:
            hits.append(self.global_vals[lo][1])
            lo += 1
            if len(hits) > 200:
                break
        pf = set(prefer_files)
        hits.sort(key=lambda i: (self.lits[i][1] not in pf, self.lits[i][1], self.lits[i][4]))
        out = []
        for i in hits[:limit]:
            _, f, ot, ow, ln = self.lits[i]
            out.append(f"{f}:{ln} {ot or ''}.{ow}")
        return out, len(hits)


# ----------------------------------------------------------------------------
# данные (JSON/CSV)
# ----------------------------------------------------------------------------
def walk_numbers(node, out):
    if isinstance(node, bool):
        return
    if isinstance(node, (int, float)):
        out.append(float(node))
    elif isinstance(node, dict):
        for v in node.values():
            walk_numbers(v, out)
    elif isinstance(node, list):
        for v in node:
            walk_numbers(v, out)
    elif isinstance(node, str):
        s = node.strip()
        try:
            out.append(float(s))
        except ValueError:
            pass


ID_KEYS = ("id", "name", "prefab", "clip", "skill", "key", "type")


class DataStore:
    def __init__(self, root, exclude):
        self.root = os.path.abspath(root)
        self.exclude = [e.strip().lower() for e in exclude.split(",") if e.strip()]
        self.files = []   # relative posix paths
        for dp, dn, fn in os.walk(self.root):
            for f in fn:
                if f.lower().endswith((".json", ".csv")):
                    self.files.append(os.path.relpath(os.path.join(dp, f), self.root).replace("\\", "/"))
        self.files.sort()
        self.by_base = defaultdict(list)
        for f in self.files:
            self.by_base[os.path.basename(f).lower()].append(f)
        self._file_scopes = {}
        self._entities = None   # name.lower() -> list[(file, values)]
        self.warnings = []

    def match_files(self, ref):
        ref = ref.replace("\\", "/").strip("/")
        low = ref.lower()
        out = []
        cands = [low, re.sub(r'^data/', '', low)]
        for c in cands:
            if "*" in c or "?" in c:
                out += [f for f in self.files if fnmatch.fnmatch(f.lower(), c) or fnmatch.fnmatch(f.lower(), "*/" + c)]
            else:
                out += [f for f in self.files if f.lower() == c or f.lower().endswith("/" + c)]
        if not out:
            out = list(self.by_base.get(os.path.basename(low), []))
        return sorted(set(out))

    def load(self, rel):
        p = os.path.join(self.root, rel)
        try:
            if rel.lower().endswith(".json"):
                with open(p, encoding="utf-8-sig") as f:
                    return json.load(f)
            with open(p, encoding="utf-8-sig", newline="") as f:
                return list(csv.DictReader(f))
        except Exception as e:  # noqa: BLE001
            self.warnings.append(f"{rel}: {e}")
            return None

    def file_scope(self, rel):
        if rel not in self._file_scopes:
            d = self.load(rel)
            vals = []
            if d is not None:
                walk_numbers(d, vals)
            self._file_scopes[rel] = Scope(rel, "data-file", vals)
        return self._file_scopes[rel]

    def _skip_entity_file(self, rel):
        low = rel.lower()
        return any(("/" + e + "/") in ("/" + low) or os.path.basename(low).startswith(e) for e in self.exclude)

    def entities(self):
        if self._entities is not None:
            return self._entities
        ents = defaultdict(list)

        def visit(node, rel):
            if isinstance(node, dict):
                names = set()
                for k, v in node.items():
                    if isinstance(v, (dict, list)):
                        names.add(str(k))
                    if str(k).lower() in ID_KEYS:
                        if isinstance(v, str):
                            names.add(v)
                        elif isinstance(v, list):
                            names.update(x for x in v if isinstance(x, str))
                if names:
                    vals = []
                    walk_numbers(node, vals)
                    if vals and len(vals) < 5000:
                        for nme in names:
                            ents[nme.lower()].append((rel, vals))
                for v in node.values():
                    visit(v, rel)
            elif isinstance(node, list):
                for v in node:
                    visit(v, rel)

        for rel in self.files:
            if self._skip_entity_file(rel):
                continue
            d = self.load(rel)
            if d is None:
                continue
            base = os.path.splitext(os.path.basename(rel))[0].lower()
            if rel.lower().endswith(".json"):
                vals = []
                walk_numbers(d, vals)
                if "/prefabs/" in "/" + rel.lower():
                    ents[base].append((rel, vals))
                visit(d, rel)
            else:
                for row in d:
                    if not row:
                        continue
                    keys = list(row.keys())
                    idv = None
                    for k in keys:
                        if k and k.lower() in ID_KEYS and row[k]:
                            idv = row[k]
                            break
                    if idv is None and keys:
                        idv = row[keys[0]]
                    vals = []
                    for v in row.values():
                        if isinstance(v, str):
                            try:
                                vals.append(float(v))
                            except ValueError:
                                pass
                    if idv and vals:
                        ents[str(idv).lower()].append((rel, vals))
        self._entities = ents
        return ents

    def entity_scopes(self, name, only_files=None):
        res = []
        for rel, vals in self.entities().get(name.lower(), []):
            if only_files is None or rel in only_files:
                res.append(Scope(f"{rel}#{name}", "data-entity", vals))
        return res


# ----------------------------------------------------------------------------
# разбор ссылок «Источник»
# ----------------------------------------------------------------------------
CS_RE = re.compile(r'([\w*?]+)\.cs\b')
DATA_RE = re.compile(r'(?:[\w.\-*]+/)*[\w.\-*]+\.(?:json|csv)\b')
IDENT_RE = re.compile(r'\b[A-Z][A-Za-z0-9_]*(?:\.[A-Za-z_]\w*)*\b')


def balanced_paren(s, i):
    """s[i] == '(' -> (содержимое, индекс после ')')."""
    depth = 0
    for j in range(i, len(s)):
        if s[j] == '(':
            depth += 1
        elif s[j] == ')':
            depth -= 1
            if depth == 0:
                return s[i + 1:j], j + 1
    return s[i + 1:], len(s)


class Resolved:
    def __init__(self):
        self.scopes = []
        self.refs = []
        self.unresolved = []


class SourceResolver:
    def __init__(self, ci, ds):
        self.ci, self.ds = ci, ds
        self.cache = {}

    def resolve(self, text):
        if text in self.cache:
            return self.cache[text]
        r = Resolved()
        t = text.replace("`", "").replace("**", "")
        # 1. файлы данных
        spans = []
        for m in DATA_RE.finditer(t):
            ref = m.group(0)
            files = self.ds.match_files(ref)
            r.refs.append(ref)
            hint = None
            rest = t[m.end():]
            mh = re.match(r'\s*\(([^)]*)\)', rest) or re.match(r'\s*,\s*([A-Za-z_]\w*)\s*(?=[,;).:]|$)', rest)
            if mh:
                hint = re.findall(r'[A-Za-z_]\w*', mh.group(1))
            if not files:
                r.unresolved.append(ref)
                spans.append((m.start(), m.end()))
                continue
            added = False
            if hint:
                for h in hint:
                    sc = self.ds.entity_scopes(h, set(files))
                    if sc:
                        r.scopes += sc
                        added = True
            for f in files:
                r.scopes.append(self.ds.file_scope(f))
            spans.append((m.start(), m.end()))
        t = self._blank(t, spans)
        # 2. файлы кода
        spans = []
        cs = list(CS_RE.finditer(t))
        for k, m in enumerate(cs):
            pat = m.group(1) + ".cs"
            files = self.ci.files_matching(pat)
            r.refs.append(pat)
            end = m.end()
            seg = ""
            rest = t[end:]
            mp = re.match(r'\s*\(', rest)
            if mp:
                seg, e2 = balanced_paren(t, end + mp.end() - 1)
                end = e2
            elif re.match(r'\s*:', rest):
                stop = len(t)
                nxt = cs[k + 1].start() if k + 1 < len(cs) else len(t)
                semi = t.find(";", end)
                stop = min(nxt, semi if semi >= 0 else len(t))
                seg = t[end + rest.index(":") + 1 - 0 if False else end:stop].lstrip(" :")
                end = stop
            spans.append((m.start(), end))
            if not files:
                r.unresolved.append(pat)
                continue
            members = [x for x in re.findall(r'[A-Za-z_][\w.]*', seg) if len(x) >= 2]
            got = []
            for mem in members:
                sc = self.ci.member_scopes(mem, files)
                if sc:
                    got += sc
                else:
                    r.unresolved.append(f"{pat}:{mem}")
            if got:
                r.scopes += got
            else:
                idx = [i for f in files for i in self.ci.by_file.get(f, [])]
                r.scopes.append(self.ci.scope_from(idx, pat + (" (файл)" if not members else " (файл, члены не найдены)"), "file"))
        t = self._blank(t, spans)
        # 3. остальные идентификаторы: типы, Type.Method, сущности данных
        seen = set()
        for m in IDENT_RE.finditer(t):
            tok = m.group(0)
            if tok in seen or len(tok) < 4:
                continue
            seen.add(tok)
            sc = self.ci.member_scopes(tok, None) if (tok in self.ci.types_by_name or "." in tok) else []
            if not sc:
                sc = self.ds.entity_scopes(tok)
            if sc:
                r.refs.append(tok)
                r.scopes += sc
        self.cache[text] = r
        return r

    @staticmethod
    def _blank(t, spans):
        if not spans:
            return t
        chars = list(t)
        for a, b in spans:
            for i in range(a, min(b, len(chars))):
                chars[i] = " "
        return "".join(chars)


# ----------------------------------------------------------------------------
# разбор markdown
# ----------------------------------------------------------------------------
class Claim:
    __slots__ = ("line", "text", "value", "raw", "pct", "unit", "times", "ctx", "section", "status", "via", "scope", "tier", "elsewhere", "n_else", "score", "srcs")

    def __init__(self, **kw):
        for k in self.__slots__:
            setattr(self, k, kw.get(k))


def strip_noise(s):
    for rx in STRIP_RES:
        s = rx.sub(lambda m: " " * len(m.group(0)), s)
    return s


def extract_numbers(line, is_table=False):
    """[(value, raw, pct, unit, times, start)] из очищенной строки."""
    s = strip_noise(line)
    s = s.replace("−", "-")
    out = []
    first_cell_skipped = not is_table
    for m in NUM_RE.finditer(s):
        sign, num, suf = m.group(1), m.group(2), m.group(3)
        if suf not in OK_SUFFIX:
            continue
        # просто ссылка на 'N-й', идентификатор и т.п. отсеяны суффиксом/lookbehind
        try:
            v = float(num)
        except ValueError:
            continue
        if sign:
            v = -v
        start = m.start()
        after = s[m.end():m.end() + 14]
        before = s[max(0, start - 2):start]
        pct = suf == "%" or after.lstrip().startswith("%")
        times = suf in ("x", "×", "х") or before.strip().endswith(("×", "x", "х")) or after.lstrip().startswith("×")
        unit = bool(suf and suf != "") or bool(UNIT_AFTER.match(after)) or pct or times
        # порядковый номер в первой ячейке таблицы
        if is_table and not first_cell_skipped:
            first_cell_skipped = True
            cell = s.split("|")[1].strip() if s.count("|") >= 2 else ""
            if re.fullmatch(r'[-−]?\d+', cell):
                if num == cell.lstrip("-−"):
                    continue
        out.append((v, (("-" if sign else "") + num + suf), pct, unit, times, start))
    return out


def is_trivial(v, unit):
    return (not unit) and v == int(v) and abs(v) <= 5


def split_blocks(lines):
    """блоки подряд идущих непустых строк; заголовок - отдельный блок. [(start, end)] (end включительно)."""
    blocks, i, n = [], 0, len(lines)
    in_code = False
    while i < n:
        if lines[i].strip().startswith("```"):
            in_code = not in_code
        if not lines[i].strip():
            i += 1
            continue
        if HEADING.match(lines[i]) and not in_code:
            blocks.append((i, i))
            i += 1
            continue
        j = i
        while j + 1 < n and lines[j + 1].strip() and not HEADING.match(lines[j + 1]):
            j += 1
        blocks.append((i, j))
        i = j + 1
    return blocks


def parse_spec(path):
    with open(path, encoding="utf-8-sig") as f:
        text = f.read()
    lines = text.splitlines()
    n = len(lines)
    # fenced code
    in_code, code_line = False, [False] * n
    for i, ln in enumerate(lines):
        if ln.strip().startswith("```"):
            in_code = not in_code
            code_line[i] = True
            continue
        code_line[i] = in_code
    blocks = split_blocks(lines)
    block_of = {}
    for bi, (a, b) in enumerate(blocks):
        for k in range(a, b + 1):
            block_of[k] = bi
    doc_src, local_src = [], defaultdict(list)    # local_src: line -> [source text]
    skip_spans = defaultdict(list)                # line -> [(a,b)] вырезать из текста утверждений
    skip_line = [False] * n
    section_of = [""] * n
    cur_section = ""
    src_section_level = None
    for i, ln in enumerate(lines):
        h = HEADING.match(ln)
        if h and not code_line[i]:
            lvl = len(h.group(1))
            title = h.group(2).strip()
            if src_section_level is not None and lvl <= src_section_level:
                src_section_level = None
            if SRC_HEADING.match(title):
                src_section_level = lvl
                skip_line[i] = True
            cur_section = title
        section_of[i] = cur_section
        if src_section_level is not None and not (h and not code_line[i]):
            skip_line[i] = True
            doc_src.append(ln)
    done_block_src = set()
    for i, ln in enumerate(lines):
        if code_line[i] or skip_line[i] or HEADING.match(ln):
            continue
        if SRC_LINE.match(ln):
            a, b = blocks[block_of[i]]
            for k in range(i, b + 1):
                skip_line[k] = True
            doc_src.append(" ".join(x.strip() for x in lines[i:b + 1]))
            continue
        for m in SRC_INLINE.finditer(ln):
            before = ln[:m.start()]
            depth = before.count("(") - before.count(")")
            rest = ln[m.end():]
            end = len(rest)
            if depth > 0:
                d = depth
                for j, ch in enumerate(rest):
                    if ch == "(":
                        d += 1
                    elif ch == ")":
                        d -= 1
                        if d < depth:
                            end = j
                            break
            src = rest[:end]
            skip_spans[i].append((m.start(), m.end() + end))
            # охват
            a, b = blocks[block_of[i]]
            covered = [i] if ENUM_ITEM.match(ln) else list(range(a, b + 1))
            if not ENUM_ITEM.match(ln) and (b == a or lines[b].rstrip().endswith(":") or True):
                nb = block_of[i] + 1
                if nb < len(blocks) and (b == a or lines[b].rstrip().endswith(":") or len(rest) == end):
                    na, nbb = blocks[nb]
                    if lines[na].lstrip().startswith("|") or ENUM_ITEM.match(lines[na]):
                        covered += list(range(na, nbb + 1))
            for k in covered:
                local_src[k].append(src)
    claims, skipped = [], 0
    for i, ln in enumerate(lines):
        if code_line[i] or skip_line[i]:
            continue
        s = ln
        h = HEADING.match(ln)
        if h:
            s = re.sub(r'^\s*\d+[a-z]?\s*[—–.\-:]\s*', '', h.group(2))
        else:
            s = ENUM_ITEM.sub("   ", s, count=1) if re.match(r'^\s*\d+[.)]\s', s) else s
        if skip_spans.get(i):
            chars = list(s)
            off = 0 if not h else 0
            for a, b in skip_spans[i]:
                for k in range(a, min(b, len(chars))):
                    chars[k] = " "
            s = "".join(chars)
        if re.match(r'^\s*\|?[\s:|-]+\|[\s:|-]*$', s):
            continue
        is_table = s.lstrip().startswith("|")
        for (v, raw, pct, unit, times, start) in extract_numbers(s, is_table):
            if is_trivial(v, unit):
                skipped += 1
                continue
            ctx = re.sub(r'\s+', ' ', ln.strip())
            if len(ctx) > 170:
                a = max(0, start - 80)
                ctx = ("…" if a else "") + ctx[a:a + 170] + "…"
            claims.append(Claim(line=i + 1, text=ctx, value=v, raw=raw, pct=pct, unit=unit, times=times, section=section_of[i],
                                srcs=list(local_src.get(i, []))))
    return {"claims": claims, "doc_src": doc_src, "skipped": skipped, "lines": n}


# ----------------------------------------------------------------------------
# проверка
# ----------------------------------------------------------------------------
def candidates(c, factors, derived):
    v = c.value
    yield v, "exact"
    if not derived:
        return
    if c.pct:
        yield v / 100.0, "% -> доля"
    elif 0 < abs(v) < 1:
        yield v * 100.0, "доля -> %"
    if v != int(v) or abs(v) >= 10:
        for n in factors:
            yield v / n, f"÷{n:g}"
            yield v * n, f"×{n:g}"


def check_claim(c, tiers, tol, factors, derived, pairs):
    """tiers: [('local'|'doc', [Scope...])]. Возвращает True/False; заполняет c.status/via/scope/tier."""
    for tier, scopes in tiers:
        for cand, via in candidates(c, factors, derived):
            for sc in scopes:
                if sc.has(cand, tol):
                    c.status, c.via, c.scope, c.tier = "MATCH", via, f"{sc.kind}:{sc.label}", tier
                    return True
    if pairs and derived and (c.value != int(c.value) or abs(c.value) >= 6):
        for tier, scopes in tiers:
            for sc in scopes:
                if sc.kind in ("method", "type", "data-entity"):
                    p = sc.pair(c.value, tol)
                    if p:
                        c.status, c.via, c.scope, c.tier = "MATCH", "произведение/частное: " + p, f"{sc.kind}:{sc.label}", tier
                        return True
    return False


def main():
    a = parse_args()
    t0 = time.time()
    factors = [float(x) for x in a.factors.split(",") if x.strip()]
    ci = CodeIndex(a.index)
    ds = DataStore(a.data, a.entity_exclude)
    res = SourceResolver(ci, ds)
    spec_files = sorted(f for f in os.listdir(a.spec) if f.lower().endswith(".md") and (not a.include or fnmatch.fnmatch(f, a.include)))
    report_files, all_notfound = {}, []
    tot = defaultdict(int)
    for fname in spec_files:
        ps = parse_spec(os.path.join(a.spec, fname))
        doc_res = Resolved()
        for s in ps["doc_src"]:
            r = res.resolve(s)
            doc_res.scopes += r.scopes
            doc_res.refs += r.refs
            doc_res.unresolved += r.unresolved
        st = defaultdict(int)
        st["skipped_trivial"] = ps["skipped"]
        nf, items = [], []
        unresolved = set(doc_res.unresolved)
        refs = set(doc_res.refs)
        for c in ps["claims"]:
            loc = Resolved()
            for s in c.srcs:
                r = res.resolve(s)
                loc.scopes += r.scopes
                loc.refs += r.refs
                loc.unresolved += r.unresolved
            unresolved.update(loc.unresolved)
            refs.update(loc.refs)
            tiers = []
            if loc.scopes:
                tiers.append(("local", loc.scopes))
            if doc_res.scopes:
                tiers.append(("doc", doc_res.scopes))
            st["claims"] += 1
            if not tiers:
                c.status = "NO_SOURCE"
                st["NO_SOURCE"] += 1
            elif check_claim(c, tiers, a.tol, factors, not a.no_derived, not a.no_pairs):
                st["MATCH"] += 1
                st["match_" + ("exact" if c.via == "exact" else "derived")] += 1
                st["match_scope_" + c.scope.split(":")[0]] += 1
            else:
                c.status = "NOT_FOUND"
                st["NOT_FOUND"] += 1
                pref = set()
                for _, scs in tiers:
                    for sc in scs:
                        if sc.kind == "file":
                            pass
                c.elsewhere, c.n_else = ci.where(c.value, a.tol)
                c.score = (3 if c.unit else 0) + (2 if c.value != int(c.value) else 0) + (1 if c.srcs else 0) + (1 if c.pct or c.times else 0)
                c.srcs = [x.strip()[:160] for x in c.srcs]
                nf.append(c)
            if a.dump_claims:
                items.append(c)
        for k, v in st.items():
            tot[k] += v
        report_files[fname] = {"stats": dict(st), "refs": sorted(refs), "unresolved_refs": sorted(unresolved),
                               "has_doc_sources": bool(doc_res.scopes), "not_found": nf, "claims": items}
        all_notfound += [(fname, c) for c in nf]
    dt = time.time() - t0
    write_reports(a, report_files, tot, all_notfound, dt, ci, ds)
    print(f"files={len(spec_files)} claims={tot['claims']} MATCH={tot['MATCH']} (exact {tot['match_exact']}, derived {tot['match_derived']}) "
          f"NOT_FOUND={tot['NOT_FOUND']} NO_SOURCE={tot['NO_SOURCE']} skipped_trivial={tot['skipped_trivial']} time={dt:.1f}s")


def esc(s):
    return s.replace("|", "\\|")


def claim_dict(fname, c):
    return {"file": fname, "line": c.line, "value": c.value, "raw": c.raw, "section": c.section, "context": c.text, "sources": c.srcs,
            "unit": c.unit, "percent": c.pct, "score": c.score, "found_in_code_elsewhere": c.elsewhere, "n_code_hits": c.n_else}


def write_reports(a, rf, tot, all_nf, dt, ci, ds):
    out_md = a.out_md or os.path.join(a.out_dir, "verify-auto.md")
    out_js = a.out_json or os.path.join(a.out_dir, "verify-auto.json")
    os.makedirs(os.path.dirname(os.path.abspath(out_md)), exist_ok=True)
    os.makedirs(os.path.dirname(os.path.abspath(out_js)), exist_ok=True)
    top = sorted(all_nf, key=lambda x: (-x[1].score, x[0], x[1].line))
    j = {
        "meta": {"tool": "verify_numbers.py", "spec": os.path.abspath(a.spec), "index": os.path.abspath(a.index), "data": os.path.abspath(a.data),
                 "tol": a.tol, "factors": a.factors, "seconds": round(dt, 2), "data_warnings": ds.warnings},
        "totals": dict(tot),
        "top_not_found": [claim_dict(f, c) for f, c in top[:a.top]],
        "files": {},
    }
    for f, d in rf.items():
        j["files"][f] = {"stats": d["stats"], "refs": d["refs"], "unresolved_refs": d["unresolved_refs"], "has_doc_sources": d["has_doc_sources"],
                         "not_found": [claim_dict(f, c) for c in d["not_found"]]}
        if a.dump_claims:
            j["files"][f]["claims"] = [dict(claim_dict(f, c), status=c.status, via=c.via, scope=c.scope, tier=c.tier) for c in d["claims"]]
    with open(out_js, "w", encoding="utf-8") as fh:
        json.dump(j, fh, ensure_ascii=False, indent=1)
    L = []
    L.append("# verify-auto: автоматическая сверка чисел спеков с кодом и данными\n")
    L.append("> Эвристика (см. `reverse-kit/verify/README.md`): MATCH = число найдено в области, на которую ссылается «Источник». "
             "NOT_FOUND - не повод считать спеку неверной: число может быть выведено, браться из другого метода/базового класса, быть описанием, а не константой.\n")
    L.append(f"- спеки: `{a.spec}`; индекс: `{a.index}` ({ci.meta['stats']['literals_num']} числовых литералов); данные: `{a.data}`")
    L.append(f"- допуск: {a.tol}; производные формы: {'выкл' if a.no_derived else 'доля<->%, ×/÷ ' + a.factors + (', пары литералов' if not a.no_pairs else '')}; время: {dt:.1f} с\n")
    L.append("## Итого\n")
    L.append("| показатель | значение |\n|---|---|")
    L.append(f"| файлов спеки | {len(rf)} |")
    L.append(f"| утверждений с числами (проверено) | {tot['claims']} |")
    L.append(f"| MATCH | {tot['MATCH']} (точно {tot['match_exact']}, производно {tot['match_derived']}) |")
    L.append(f"| NOT_FOUND | {tot['NOT_FOUND']} |")
    L.append(f"| NO_SOURCE | {tot['NO_SOURCE']} |")
    L.append(f"| пропущено как тривиальные (целые 0..5 без единицы) | {tot['skipped_trivial']} |")
    L.append(f"| MATCH по областям: метод/тип | {tot['match_scope_method'] + tot['match_scope_type']} |")
    L.append(f"| MATCH по областям: файл целиком (слабее) | {tot['match_scope_file']} |")
    L.append(f"| MATCH по областям: данные | {tot['match_scope_data-file'] + tot['match_scope_data-entity']} |\n")
    L.append(f"## Топ-{a.top} NOT_FOUND (по весу: единица измерения, нецелое, локальный источник)\n")
    L.append("| # | файл:строка | число | контекст | есть в коде в другом месте |\n|---|---|---|---|---|")
    for k, (f, c) in enumerate(top[:a.top], 1):
        el = "; ".join(c.elsewhere) + (f" (всего {c.n_else})" if c.n_else > len(c.elsewhere) else "") if c.elsewhere else "-"
        L.append(f"| {k} | {f}:{c.line} | `{c.raw}` | {esc(c.text)} | {esc(el)} |")
    L.append("\n## По файлам\n")
    L.append("| файл | утв. | MATCH | NOT_FOUND | NO_SOURCE | тривиальных | ссылок найдено/не найдено |\n|---|---|---|---|---|---|---|")
    for f, d in rf.items():
        s = d["stats"]
        L.append(f"| {f} | {s.get('claims', 0)} | {s.get('MATCH', 0)} | {s.get('NOT_FOUND', 0)} | {s.get('NO_SOURCE', 0)} | {s.get('skipped_trivial', 0)} | {len(d['refs'])}/{len(d['unresolved_refs'])} |")
    L.append("\n## NOT_FOUND по файлам\n")
    for f, d in rf.items():
        if not d["not_found"]:
            continue
        L.append(f"### {f} - NOT_FOUND: {len(d['not_found'])}\n")
        if d["unresolved_refs"]:
            L.append("Не разрешены ссылки: " + ", ".join(f"`{x}`" for x in d["unresolved_refs"][:25]) + ("..." if len(d["unresolved_refs"]) > 25 else "") + "\n")
        for c in sorted(d["not_found"], key=lambda c: c.line)[:a.max_notfound]:
            el = f" - в коде: {'; '.join(c.elsewhere[:2])}" if c.elsewhere else ""
            L.append(f"- L{c.line} `{c.raw}` - {esc(c.text)}{el}")
        if len(d["not_found"]) > a.max_notfound:
            L.append(f"- ... ещё {len(d['not_found']) - a.max_notfound} (полный список в JSON)")
        L.append("")
    nosrc = [f for f, d in rf.items() if d["stats"].get("NO_SOURCE")]
    if nosrc:
        L.append("## Файлы с NO_SOURCE (нет разрешимых ссылок «Источник»)\n")
        L.append(", ".join(f"{f} ({rf[f]['stats']['NO_SOURCE']})" for f in nosrc) + "\n")
    if ds.warnings:
        L.append("## Предупреждения чтения данных\n")
        L += [f"- {w}" for w in ds.warnings[:20]]
    with open(out_md, "w", encoding="utf-8") as fh:
        fh.write("\n".join(L) + "\n")
    print("report:", out_md, out_js)


if __name__ == "__main__":
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    main()

