#!/usr/bin/env python3
"""verify_numbers.py - эвристическая сверка чисел в спеках с кодом (index.json) и данными.

    python verify_numbers.py --spec <dir> --index <index.json> --data <data_dir> [--out-dir DIR]

Для каждого .md в --spec ищет утверждения с числами и ссылки «Источник: ...»,
проверяет, что число встречается как литерал в указанном методе/типе/файле
(через index.json от codeindex) либо как значение в указанном JSON/CSV.
Спеки только читаются. Это ЭВРИСТИКА - см. README.md (ограничения).
"""
import argparse
import bisect
import csv
import fnmatch
import json
import os
import re
import sys
import time
from collections import defaultdict

# ----------------------------------------------------------------------------
# числа в тексте
# ----------------------------------------------------------------------------
NUM_RE = re.compile(r'(?:(?<![\w.)\]])([-\u2212])(?=\d))?(?<![\w.])(\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)([A-Za-z\u0410-\u044f\u00b0%\u00d7]*)')
OK_SUFFIX = {"", "%", "\u0441", "\u0441\u0435\u043a", "\u043c", "\u043c\u0441", "f", "F", "x", "\u00d7", "s", "ms", "m", "px", "\u00b0",
             "\u0413\u0446", "Hz", "hp", "HP", "\u0445"}
UNIT_AFTER = re.compile(r'^\s?(?:\u0441(?![\w])|\u0441\u0435\u043a|\u043c/\u0441|\u043c(?![\w])|\u043c\u0441|%|\u00d7|px|HP|\u0425\u041f|\u0413\u0446|\u0442\u0438\u043a\w*|\u043a\u0430\u0434\u0440\w*|'
                        r'\u0440\u0430\u0437(?![\w])|\u0435\u0434\.?|\u0448\u0442|\u0433\u0440\u0430\u0434\u0443\u0441\w*|\u00b0|\u043a\u043b\u0435\u0442\w*|\u043f\u0438\u043a\u0441\w*|\u043e\u0447\w*|\u0443\u0440\u043e\u043d\w*|\u0441\u0435\u043a\u0443\u043d\u0434\w*|\u043c\u0435\u0442\u0440\w*)')

STRIP_RES = [
    re.compile(r'https?://\S+'),
    re.compile(r'[\w/.*\-]+\.(?:cs|json|csv|md|prefab|asset|py|toml|png|wav|ogg)\b'),
    re.compile(r'\b\d{2}[a-z]?-[A-Za-z][\w-]*'),                      # 00-core, 05b-arcana
    re.compile(r'\u2116\s*\d+[a-z]?'),                                  # №12
    re.compile(r'\b(?:\u043f|\u043f\u043f)\.\s*\d+(?:[.,\u2013-]\d+)*'),                    # п. 9
    re.compile(r'(?i)\b(?:\u043f\u0443\u043d\u043a\u0442\w*|\u0440\u0430\u0437\u0434\u0435\u043b\w*|\u0442\u0430\u0431\u043b\w*|\u0441\u0440\u0435\u0437\w*|\u0441\u0442\u0430\u0434\u0438\w*|\u0444\u0430\u0437\w*|\u0448\u0430\u0433\w*|\u0433\u043b\u0430\u0432\w*|\u0440\u0435\u0432\u0438\u0437\u0438\w*|\u0432\u0435\u0440\u0441\u0438\u044f|\u0442\u0438\u0440)\s+(?:\w+\s+)?\d+'),
    re.compile(r'(?<![\w.])#\d+'),
]

