def walk_numbers(node, out):
    if isinstance(node, bool):
        return
    if isinstance(node, (int, float)):
        out.append(float(node))
    elif isinstance(node, dict):
        for v in node.values():
            walk_numbers(v, out)
    elif isinstance(node, list):
        for v in node:
            walk_numbers(v, out)
    elif isinstance(node, str):
        s = node.strip()
        try:
            out.append(float(s))
        except ValueError:
            pass


ID_KEYS = ("id", "name", "prefab", "clip", "skill", "key", "type")


class DataStore:
    def __init__(self, root, exclude):
        self.root = os.path.abspath(root)
        self.exclude = [e.strip().lower() for e in exclude.split(",") if e.strip()]
        self.files = []   # relative posix paths
        for dp, dn, fn in os.walk(self.root):
            for f in fn:
                if f.lower().endswith((".json", ".csv")):
                    self.files.append(os.path.relpath(os.path.join(dp, f), self.root).replace("\\", "/"))
        self.files.sort()
        self.by_base = defaultdict(list)
        for f in self.files:
            self.by_base[os.path.basename(f).lower()].append(f)
        self._file_scopes = {}
        self._entities = None   # name.lower() -> list[(file, values)]
        self.warnings = []

    def match_files(self, ref):
        ref = ref.replace("\\", "/").strip("/")
        low = ref.lower()
        out = []
        cands = [low, re.sub(r'^data/', '', low)]
        for c in cands:
            if "*" in c or "?" in c:
                out += [f for f in self.files if fnmatch.fnmatch(f.lower(), c) or fnmatch.fnmatch(f.lower(), "*/" + c)]
            else:
                out += [f for f in self.files if f.lower() == c or f.lower().endswith("/" + c)]
        if not out:
            out = list(self.by_base.get(os.path.basename(low), []))
        return sorted(set(out))

    def load(self, rel):
        p = os.path.join(self.root, rel)
        try:
            if rel.lower().endswith(".json"):
                with open(p, encoding="utf-8-sig") as f:
                    return json.load(f)
            with open(p, encoding="utf-8-sig", newline="") as f:
                return list(csv.DictReader(f))
        except Exception as e:  # noqa: BLE001
            self.warnings.append(f"{rel}: {e}")
            return None

    def file_scope(self, rel):
        if rel not in self._file_scopes:
            d = self.load(rel)
            vals = []
            if d is not None:
                walk_numbers(d, vals)
            self._file_scopes[rel] = Scope(rel, "data-file", vals)
        return self._file_scopes[rel]

    def _skip_entity_file(self, rel):
        low = rel.lower()
        return any(("/" + e + "/") in ("/" + low) or os.path.basename(low).startswith(e) for e in self.exclude)

    def entities(self):
        if self._entities is not None:
            return self._entities
        ents = defaultdict(list)

        def visit(node, rel):
            if isinstance(node, dict):
                names = set()
                for k, v in node.items():
                    if isinstance(v, (dict, list)):
                        names.add(str(k))
                    if str(k).lower() in ID_KEYS:
                        if isinstance(v, str):
                            names.add(v)
                        elif isinstance(v, list):
                            names.update(x for x in v if isinstance(x, str))
                if names:
                    vals = []
                    walk_numbers(node, vals)
                    if vals and len(vals) < 5000:
                        for nme in names:
                            ents[nme.lower()].append((rel, vals))
                for v in node.values():
                    visit(v, rel)
            elif isinstance(node, list):
                for v in node:
                    visit(v, rel)

        for rel in self.files:
            if self._skip_entity_file(rel):
                continue
            d = self.load(rel)
            if d is None:
                continue
            base = os.path.splitext(os.path.basename(rel))[0].lower()
            if rel.lower().endswith(".json"):
                vals = []
                walk_numbers(d, vals)
                if "/prefabs/" in "/" + rel.lower():
                    ents[base].append((rel, vals))
                visit(d, rel)
            else:
                for row in d:
                    if not row:
                        continue
                    keys = list(row.keys())
                    idv = None
                    for k in keys:
                        if k and k.lower() in ID_KEYS and row[k]:
                            idv = row[k]
                            break
                    if idv is None and keys:
                        idv = row[keys[0]]
                    vals = []
                    for v in row.values():
                        if isinstance(v, str):
                            try:
                                vals.append(float(v))
                            except ValueError:
                                pass
                    if idv and vals:
                        ents[str(idv).lower()].append((rel, vals))
        self._entities = ents
        return ents

    def entity_scopes(self, name, only_files=None):
        res = []
        for rel, vals in self.entities().get(name.lower(), []):
            if only_files is None or rel in only_files:
                res.append(Scope(f"{rel}#{name}", "data-entity", vals))
        return res


