# разбор ссылок «Источник»
# ----------------------------------------------------------------------------
CS_RE = re.compile(r'([\w*?]+)\.cs\b')
DATA_RE = re.compile(r'(?:[\w.\-*]+/)*[\w.\-*]+\.(?:json|csv)\b')
IDENT_RE = re.compile(r'\b[A-Z][A-Za-z0-9_]*(?:\.[A-Za-z_]\w*)*\b')


def balanced_paren(s, i):
    """s[i] == '(' -> (содержимое, индекс после ')')."""
    depth = 0
    for j in range(i, len(s)):
        if s[j] == '(':
            depth += 1
        elif s[j] == ')':
            depth -= 1
            if depth == 0:
                return s[i + 1:j], j + 1
    return s[i + 1:], len(s)


class Resolved:
    def __init__(self):
        self.scopes = []
        self.refs = []
        self.unresolved = []


class SourceResolver:
    def __init__(self, ci, ds):
        self.ci, self.ds = ci, ds
        self.cache = {}

    def resolve(self, text):
        if text in self.cache:
            return self.cache[text]
        r = Resolved()
        t = text.replace("`", "").replace("**", "")
        # 1. файлы данных
        spans = []
        for m in DATA_RE.finditer(t):
            ref = m.group(0)
            files = self.ds.match_files(ref)
            r.refs.append(ref)
            hint = None
            rest = t[m.end():]
            mh = re.match(r'\s*\(([^)]*)\)', rest) or re.match(r'\s*,\s*([A-Za-z_]\w*)\s*(?=[,;).:]|$)', rest)
            if mh:
                hint = re.findall(r'[A-Za-z_]\w*', mh.group(1))
            if not files:
                r.unresolved.append(ref)
                spans.append((m.start(), m.end()))
                continue
            added = False
            if hint:
                for h in hint:
                    sc = self.ds.entity_scopes(h, set(files))
                    if sc:
                        r.scopes += sc
                        added = True
            for f in files:
                r.scopes.append(self.ds.file_scope(f))
            spans.append((m.start(), m.end()))
        t = self._blank(t, spans)
        # 2. файлы кода
        spans = []
        cs = list(CS_RE.finditer(t))
        for k, m in enumerate(cs):
            pat = m.group(1) + ".cs"
            files = self.ci.files_matching(pat)
            r.refs.append(pat)
            end = m.end()
            seg = ""
            rest = t[end:]
            mp = re.match(r'\s*\(', rest)
            if mp:
                seg, e2 = balanced_paren(t, end + mp.end() - 1)
                end = e2
            elif re.match(r'\s*:', rest):
                stop = len(t)
                nxt = cs[k + 1].start() if k + 1 < len(cs) else len(t)
                semi = t.find(";", end)
                stop = min(nxt, semi if semi >= 0 else len(t))
                seg = t[end + rest.index(":") + 1 - 0 if False else end:stop].lstrip(" :")
                end = stop
            spans.append((m.start(), end))
            if not files:
                r.unresolved.append(pat)
                continue
            members = [x for x in re.findall(r'[A-Za-z_][\w.]*', seg) if len(x) >= 2]
            got = []
            for mem in members:
                sc = self.ci.member_scopes(mem, files)
                if sc:
                    got += sc
                else:
                    r.unresolved.append(f"{pat}:{mem}")
            if got:
                r.scopes += got
            else:
                idx = [i for f in files for i in self.ci.by_file.get(f, [])]
                r.scopes.append(self.ci.scope_from(idx, pat + (" (файл)" if not members else " (файл, члены не найдены)"), "file"))
        t = self._blank(t, spans)
        # 3. остальные идентификаторы: типы, Type.Method, сущности данных
        seen = set()
        for m in IDENT_RE.finditer(t):
            tok = m.group(0)
            if tok in seen or len(tok) < 4:
                continue
            seen.add(tok)
            sc = self.ci.member_scopes(tok, None) if (tok in self.ci.types_by_name or "." in tok) else []
            if not sc:
                sc = self.ds.entity_scopes(tok)
            if sc:
                r.refs.append(tok)
                r.scopes += sc
        self.cache[text] = r
        return r

    @staticmethod
    def _blank(t, spans):
        if not spans:
            return t
        chars = list(t)
        for a, b in spans:
            for i in range(a, min(b, len(chars))):
                chars[i] = " "
        return "".join(chars)


