class Claim:
    __slots__ = ("line", "text", "value", "raw", "pct", "unit", "times", "ctx", "section", "status", "via", "scope", "tier", "elsewhere", "n_else", "score", "srcs")

    def __init__(self, **kw):
        for k in self.__slots__:
            setattr(self, k, kw.get(k))


def strip_noise(s):
    for rx in STRIP_RES:
        s = rx.sub(lambda m: " " * len(m.group(0)), s)
    return s


def extract_numbers(line, is_table=False):
    """[(value, raw, pct, unit, times, start)] из очищенной строки."""
    s = strip_noise(line)
    s = s.replace("\u2212", "-")
    out = []
    first_cell_skipped = not is_table
    for m in NUM_RE.finditer(s):
        sign, num, suf = m.group(1), m.group(2), m.group(3)
        if suf not in OK_SUFFIX:
            continue
        # просто ссылка на 'N-й', идентификатор и т.п. отсеяны суффиксом/lookbehind
        try:
            v = float(num)
        except ValueError:
            continue
        if sign:
            v = -v
        start = m.start()
        after = s[m.end():m.end() + 14]
        before = s[max(0, start - 2):start]
        pct = suf == "%" or after.lstrip().startswith("%")
        times = suf in ("x", "\u00d7", "\u0445") or before.strip().endswith(("\u00d7", "x", "\u0445")) or after.lstrip().startswith("\u00d7")
        unit = bool(suf and suf != "") or bool(UNIT_AFTER.match(after)) or pct or times
        # порядковый номер в первой ячейке таблицы
        if is_table and not first_cell_skipped:
            first_cell_skipped = True
            cell = s.split("|")[1].strip() if s.count("|") >= 2 else ""
            if re.fullmatch(r'[-\u2212]?\d+', cell):
                if num == cell.lstrip("-\u2212"):
                    continue
        out.append((v, (("-" if sign else "") + num + suf), pct, unit, times, start))
    return out


def is_trivial(v, unit):
    return (not unit) and v == int(v) and abs(v) <= 5


def split_blocks(lines):
    """блоки подряд идущих непустых строк; заголовок - отдельный блок. [(start, end)] (end включительно)."""
    blocks, i, n = [], 0, len(lines)
    in_code = False
    while i < n:
        if lines[i].strip().startswith("```"):
            in_code = not in_code
        if not lines[i].strip():
            i += 1
            continue
        if HEADING.match(lines[i]) and not in_code:
            blocks.append((i, i))
            i += 1
            continue
        j = i
        while j + 1 < n and lines[j + 1].strip() and not HEADING.match(lines[j + 1]):
            j += 1
        blocks.append((i, j))
        i = j + 1
    return blocks


def parse_spec(path):
    with open(path, encoding="utf-8-sig") as f:
        text = f.read()
    lines = text.splitlines()
    n = len(lines)
    # fenced code
    in_code, code_line = False, [False] * n
    for i, ln in enumerate(lines):
        if ln.strip().startswith("```"):
            in_code = not in_code
            code_line[i] = True
            continue
        code_line[i] = in_code
    blocks = split_blocks(lines)
    block_of = {}
    for bi, (a, b) in enumerate(blocks):
        for k in range(a, b + 1):
            block_of[k] = bi
    doc_src, local_src = [], defaultdict(list)    # local_src: line -> [source text]
    skip_spans = defaultdict(list)                # line -> [(a,b)] вырезать из текста утверждений
    skip_line = [False] * n
    section_of = [""] * n
    cur_section = ""
    src_section_level = None
    for i, ln in enumerate(lines):
        h = HEADING.match(ln)
        if h and not code_line[i]:
            lvl = len(h.group(1))
            title = h.group(2).strip()
            if src_section_level is not None and lvl <= src_section_level:
                src_section_level = None
            if SRC_HEADING.match(title):
                src_section_level = lvl
                skip_line[i] = True
            cur_section = title
        section_of[i] = cur_section
        if src_section_level is not None and not (h and not code_line[i]):
            skip_line[i] = True
            doc_src.append(ln)
    done_block_src = set()
    for i, ln in enumerate(lines):
        if code_line[i] or skip_line[i] or HEADING.match(ln):
            continue
        if SRC_LINE.match(ln):
            a, b = blocks[block_of[i]]
            for k in range(i, b + 1):
                skip_line[k] = True
            doc_src.append(" ".join(x.strip() for x in lines[i:b + 1]))
            continue
        for m in SRC_INLINE.finditer(ln):
            before = ln[:m.start()]
            depth = before.count("(") - before.count(")")
            rest = ln[m.end():]
            end = len(rest)
            if depth > 0:
                d = depth
                for j, ch in enumerate(rest):
                    if ch == "(":
                        d += 1
                    elif ch == ")":
                        d -= 1
                        if d < depth:
                            end = j
                            break
            src = rest[:end]
            skip_spans[i].append((m.start(), m.end() + end))
            # охват
            a, b = blocks[block_of[i]]
            covered = [i] if ENUM_ITEM.match(ln) else list(range(a, b + 1))
            if not ENUM_ITEM.match(ln) and (b == a or lines[b].rstrip().endswith(":") or True):
                nb = block_of[i] + 1
                if nb < len(blocks) and (b == a or lines[b].rstrip().endswith(":") or len(rest) == end):
                    na, nbb = blocks[nb]
                    if lines[na].lstrip().startswith("|") or ENUM_ITEM.match(lines[na]):
                        covered += list(range(na, nbb + 1))
            for k in covered:
                local_src[k].append(src)
    claims, skipped = [], 0
    for i, ln in enumerate(lines):
        if code_line[i] or skip_line[i]:
            continue
        s = ln
        h = HEADING.match(ln)
        if h:
            s = re.sub(r'^\s*\d+[a-z]?\s*[\u2014\u2013.\-:]\s*', '', h.group(2))
        else:
            s = ENUM_ITEM.sub("   ", s, count=1) if re.match(r'^\s*\d+[.)]\s', s) else s
        if skip_spans.get(i):
            chars = list(s)
            off = 0 if not h else 0
            for a, b in skip_spans[i]:
                for k in range(a, min(b, len(chars))):
                    chars[k] = " "
            s = "".join(chars)
        if re.match(r'^\s*\|?[\s:|-]+\|[\s:|-]*$', s):
            continue
        is_table = s.lstrip().startswith("|")
        for (v, raw, pct, unit, times, start) in extract_numbers(s, is_table):
            if is_trivial(v, unit):
                skipped += 1
                continue
            ctx = re.sub(r'\s+', ' ', ln.strip())
            if len(ctx) > 170:
                a = max(0, start - 80)
                ctx = ("\u2026" if a else "") + ctx[a:a + 170] + "\u2026"
            claims.append(Claim(line=i + 1, text=ctx, value=v, raw=raw, pct=pct, unit=unit, times=times, section=section_of[i],
                                srcs=list(local_src.get(i, []))))
    return {"claims": claims, "doc_src": doc_src, "skipped": skipped, "lines": n}


# ----------------------------------------------------------------------------
# проверка
# ----------------------------------------------------------------------------
def candidates(c, factors, derived):
    v = c.value
    yield v, "exact"
    if not derived:
        return
    if c.pct:
        yield v / 100.0, "% -> доля"
    elif 0 < abs(v) < 1:
        yield v * 100.0, "доля -> %"
    if v != int(v) or abs(v) >= 10:
        for n in factors:
            yield v / n, f"\u00f7{n:g}"
            yield v * n, f"\u00d7{n:g}"


def check_claim(c, tiers, tol, factors, derived, pairs):
    """tiers: [('local'|'doc', [Scope...])]. Возвращает True/False; заполняет c.status/via/scope/tier."""
    for tier, scopes in tiers:
        for cand, via in candidates(c, factors, derived):
            for sc in scopes:
                if sc.has(cand, tol):
                    c.status, c.via, c.scope, c.tier = "MATCH", via, f"{sc.kind}:{sc.label}", tier
                    return True
    if pairs and derived and (c.value != int(c.value) or abs(c.value) >= 6):
        for tier, scopes in tiers:
            for sc in scopes:
                if sc.kind in ("method", "type", "data-entity"):
                    p = sc.pair(c.value, tol)
                    if p:
                        c.status, c.via, c.scope, c.tier = "MATCH", "произведение/частное: " + p, f"{sc.kind}:{sc.label}", tier
                        return True
    return False


def main():
    a = parse_args()
    t0 = time.time()
    factors = [float(x) for x in a.factors.split(",") if x.strip()]
    ci = CodeIndex(a.index)
    ds = DataStore(a.data, a.entity_exclude)
    res = SourceResolver(ci, ds)
    spec_files = sorted(f for f in os.listdir(a.spec) if f.lower().endswith(".md") and (not a.include or fnmatch.fnmatch(f, a.include)))
    report_files, all_notfound = {}, []
    tot = defaultdict(int)
    for fname in spec_files:
        ps = parse_spec(os.path.join(a.spec, fname))
        doc_res = Resolved()
        for s in ps["doc_src"]:
            r = res.resolve(s)
            doc_res.scopes += r.scopes
            doc_res.refs += r.refs
            doc_res.unresolved += r.unresolved
        st = defaultdict(int)
        st["skipped_trivial"] = ps["skipped"]
        nf, items = [], []
        unresolved = set(doc_res.unresolved)
        refs = set(doc_res.refs)
        for c in ps["claims"]:
            loc = Resolved()
            for s in c.srcs:
                r = res.resolve(s)
                loc.scopes += r.scopes
                loc.refs += r.refs
                loc.unresolved += r.unresolved
            unresolved.update(loc.unresolved)
            refs.update(loc.refs)
            tiers = []
            if loc.scopes:
                tiers.append(("local", loc.scopes))
            if doc_res.scopes:
                tiers.append(("doc", doc_res.scopes))
            st["claims"] += 1
            if not tiers:
                c.status = "NO_SOURCE"
                st["NO_SOURCE"] += 1
            elif check_claim(c, tiers, a.tol, factors, not a.no_derived, not a.no_pairs):
                st["MATCH"] += 1
                st["match_" + ("exact" if c.via == "exact" else "derived")] += 1
                st["match_scope_" + c.scope.split(":")[0]] += 1
            else:
                c.status = "NOT_FOUND"
                st["NOT_FOUND"] += 1
                pref = set()
                for _, scs in tiers:
                    for sc in scs:
                        if sc.kind == "file":
                            pass
                c.elsewhere, c.n_else = ci.where(c.value, a.tol)
                c.score = (3 if c.unit else 0) + (2 if c.value != int(c.value) else 0) + (1 if c.srcs else 0) + (1 if c.pct or c.times else 0)
                c.srcs = [x.strip()[:160] for x in c.srcs]
                nf.append(c)
            if a.dump_claims:
                items.append(c)
        for k, v in st.items():
            tot[k] += v
        report_files[fname] = {"stats": dict(st), "refs": sorted(refs), "unresolved_refs": sorted(unresolved),
                               "has_doc_sources": bool(doc_res.scopes), "not_found": nf, "claims": items}
        all_notfound += [(fname, c) for c in nf]
    dt = time.time() - t0
    write_reports(a, report_files, tot, all_notfound, dt, ci, ds)
    print(f"files={len(spec_files)} claims={tot['claims']} MATCH={tot['MATCH']} (exact {tot['match_exact']}, derived {tot['match_derived']}) "
          f"NOT_FOUND={tot['NOT_FOUND']} NO_SOURCE={tot['NO_SOURCE']} skipped_trivial={tot['skipped_trivial']} time={dt:.1f}s")


def esc(s):
    return s.replace("|", "\\|")


def claim_dict(fname, c):
    return {"file": fname, "line": c.line, "value": c.value, "raw": c.raw, "section": c.section, "context": c.text, "sources": c.srcs,
            "unit": c.unit, "percent": c.pct, "score": c.score, "found_in_code_elsewhere": c.elsewhere, "n_code_hits": c.n_else}


def write_reports(a, rf, tot, all_nf, dt, ci, ds):
    out_md = a.out_md or os.path.join(a.out_dir, "verify-auto.md")
    out_js = a.out_json or os.path.join(a.out_dir, "verify-auto.json")
    os.makedirs(os.path.dirname(os.path.abspath(out_md)), exist_ok=True)
    os.makedirs(os.path.dirname(os.path.abspath(out_js)), exist_ok=True)
    top = sorted(all_nf, key=lambda x: (-x[1].score, x[0], x[1].line))
    j = {
        "meta": {"tool": "verify_numbers.py", "spec": os.path.abspath(a.spec), "index": os.path.abspath(a.index), "data": os.path.abspath(a.data),
                 "tol": a.tol, "factors": a.factors, "seconds": round(dt, 2), "data_warnings": ds.warnings},
        "totals": dict(tot),
        "top_not_found": [claim_dict(f, c) for f, c in top[:a.top]],
        "files": {},
    }
    for f, d in rf.items():
        j["files"][f] = {"stats": d["stats"], "refs": d["refs"], "unresolved_refs": d["unresolved_refs"], "has_doc_sources": d["has_doc_sources"],
                         "not_found": [claim_dict(f, c) for c in d["not_found"]]}
        if a.dump_claims:
            j["files"][f]["claims"] = [dict(claim_dict(f, c), status=c.status, via=c.via, scope=c.scope, tier=c.tier) for c in d["claims"]]
    with open(out_js, "w", encoding="utf-8") as fh:
        json.dump(j, fh, ensure_ascii=False, indent=1)
    L = []
    L.append("# verify-auto: автоматическая сверка чисел спеков с кодом и данными\n")
    L.append("> Эвристика (см. `reverse-kit/verify/README.md`): MATCH = число найдено в области, на которую ссылается «Источник». "
             "NOT_FOUND - не повод считать спеку неверной: число может быть выведено, браться из другого метода/базового класса, быть описанием, а не константой.\n")
    L.append(f"- спеки: `{a.spec}`; индекс: `{a.index}` ({ci.meta['stats']['literals_num']} числовых литералов); данные: `{a.data}`")
    L.append(f"- допуск: {a.tol}; производные формы: {'выкл' if a.no_derived else 'доля<->%, ×/÷ ' + a.factors + (', пары литералов' if not a.no_pairs else '')}; время: {dt:.1f} с\n")
    L.append("## Итого\n")
    L.append("| показатель | значение |\n|---|---|")
    L.append(f"| файлов спеки | {len(rf)} |")
    L.append(f"| утверждений с числами (проверено) | {tot['claims']} |")
    L.append(f"| MATCH | {tot['MATCH']} (точно {tot['match_exact']}, производно {tot['match_derived']}) |")
    L.append(f"| NOT_FOUND | {tot['NOT_FOUND']} |")
    L.append(f"| NO_SOURCE | {tot['NO_SOURCE']} |")
    L.append(f"| пропущено как тривиальные (целые 0..5 без единицы) | {tot['skipped_trivial']} |")
    L.append(f"| MATCH по областям: метод/тип | {tot['match_scope_method'] + tot['match_scope_type']} |")
    L.append(f"| MATCH по областям: файл целиком (слабее) | {tot['match_scope_file']} |")
    L.append(f"| MATCH по областям: данные | {tot['match_scope_data-file'] + tot['match_scope_data-entity']} |\n")
    L.append(f"## Топ-{a.top} NOT_FOUND (по весу: единица измерения, нецелое, локальный источник)\n")
    L.append("| # | файл:строка | число | контекст | есть в коде в другом месте |\n|---|---|---|---|---|")
    for k, (f, c) in enumerate(top[:a.top], 1):
        el = "; ".join(c.elsewhere) + (f" (всего {c.n_else})" if c.n_else > len(c.elsewhere) else "") if c.elsewhere else "-"
        L.append(f"| {k} | {f}:{c.line} | `{c.raw}` | {esc(c.text)} | {esc(el)} |")
    L.append("\n## По файлам\n")
    L.append("| файл | утв. | MATCH | NOT_FOUND | NO_SOURCE | тривиальных | ссылок найдено/не найдено |\n|---|---|---|---|---|---|---|")
    for f, d in rf.items():
        s = d["stats"]
        L.append(f"| {f} | {s.get('claims', 0)} | {s.get('MATCH', 0)} | {s.get('NOT_FOUND', 0)} | {s.get('NO_SOURCE', 0)} | {s.get('skipped_trivial', 0)} | {len(d['refs'])}/{len(d['unresolved_refs'])} |")
    L.append("\n## NOT_FOUND по файлам\n")
    for f, d in rf.items():
        if not d["not_found"]:
            continue
        L.append(f"### {f} - NOT_FOUND: {len(d['not_found'])}\n")
        if d["unresolved_refs"]:
            L.append("Не разрешены ссылки: " + ", ".join(f"`{x}`" for x in d["unresolved_refs"][:25]) + ("..." if len(d["unresolved_refs"]) > 25 else "") + "\n")
        for c in sorted(d["not_found"], key=lambda c: c.line)[:a.max_notfound]:
            el = f" - в коде: {'; '.join(c.elsewhere[:2])}" if c.elsewhere else ""
            L.append(f"- L{c.line} `{c.raw}` - {esc(c.text)}{el}")
        if len(d["not_found"]) > a.max_notfound:
            L.append(f"- ... ещё {len(d['not_found']) - a.max_notfound} (полный список в JSON)")
        L.append("")
    nosrc = [f for f, d in rf.items() if d["stats"].get("NO_SOURCE")]
    if nosrc:
        L.append("## Файлы с NO_SOURCE (нет разрешимых ссылок «Источник»)\n")
        L.append(", ".join(f"{f} ({rf[f]['stats']['NO_SOURCE']})" for f in nosrc) + "\n")
    if ds.warnings:
        L.append("## Предупреждения чтения данных\n")
        L += [f"- {w}" for w in ds.warnings[:20]]
    with open(out_md, "w", encoding="utf-8") as fh:
        fh.write("\n".join(L) + "\n")
    print("report:", out_md, out_js)


if __name__ == "__main__":
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    main()

