#!/usr/bin/env python3
"""verify_numbers.py - эвристическая сверка чисел в спеках с кодом (index.json) и данными.

    python verify_numbers.py --spec <dir> --index <index.json> --data <data_dir> [--out-dir DIR]

Для каждого .md в --spec ищет утверждения с числами и ссылки «Источник: ...»,
проверяет, что число встречается как литерал в указанном методе/типе/файле
(через index.json от codeindex) либо как значение в указанном JSON/CSV.
Спеки только читаются. Это ЭВРИСТИКА - см. README.md (ограничения).
"""
import argparse
import bisect
import csv
import fnmatch
import json
import os
import re
import sys
import time
from collections import defaultdict

# ----------------------------------------------------------------------------
# числа в тексте
# ----------------------------------------------------------------------------
NUM_RE = re.compile(r'(?:(?<![\w.)\]])([-\u2212])(?=\d))?(?<![\w.])(\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)([A-Za-z\u0410-\u044f\u00b0%\u00d7]*)')
OK_SUFFIX = {"", "%", "\u0441", "\u0441\u0435\u043a", "\u043c", "\u043c\u0441", "f", "F", "x", "\u00d7", "s", "ms", "m", "px", "\u00b0",
             "\u0413\u0446", "Hz", "hp", "HP", "\u0445"}
UNIT_AFTER = re.compile(r'^\s?(?:\u0441(?![\w])|\u0441\u0435\u043a|\u043c/\u0441|\u043c(?![\w])|\u043c\u0441|%|\u00d7|px|HP|\u0425\u041f|\u0413\u0446|\u0442\u0438\u043a\w*|\u043a\u0430\u0434\u0440\w*|'
                        r'\u0440\u0430\u0437(?![\w])|\u0435\u0434\.?|\u0448\u0442|\u0433\u0440\u0430\u0434\u0443\u0441\w*|\u00b0|\u043a\u043b\u0435\u0442\w*|\u043f\u0438\u043a\u0441\w*|\u043e\u0447\w*|\u0443\u0440\u043e\u043d\w*|\u0441\u0435\u043a\u0443\u043d\u0434\w*|\u043c\u0435\u0442\u0440\w*)')

STRIP_RES = [
    re.compile(r'https?://\S+'),
    re.compile(r'[\w/.*\-]+\.(?:cs|json|csv|md|prefab|asset|py|toml|png|wav|ogg)\b'),
    re.compile(r'\b\d{2}[a-z]?-[A-Za-z][\w-]*'),                      # 00-core, 05b-arcana
    re.compile(r'\u2116\s*\d+[a-z]?'),                                  # №12
    re.compile(r'\b(?:\u043f|\u043f\u043f)\.\s*\d+(?:[.,\u2013-]\d+)*'),                    # п. 9
    re.compile(r'(?i)\b(?:\u043f\u0443\u043d\u043a\u0442\w*|\u0440\u0430\u0437\u0434\u0435\u043b\w*|\u0442\u0430\u0431\u043b\w*|\u0441\u0440\u0435\u0437\w*|\u0441\u0442\u0430\u0434\u0438\w*|\u0444\u0430\u0437\w*|\u0448\u0430\u0433\w*|\u0433\u043b\u0430\u0432\w*|\u0440\u0435\u0432\u0438\u0437\u0438\w*|\u0432\u0435\u0440\u0441\u0438\u044f|\u0442\u0438\u0440)\s+(?:\w+\s+)?\d+'),
    re.compile(r'(?<![\w.])#\d+'),
]

ENUM_ITEM = re.compile(r'^\s*(?:\d+[.)]|[-*+])\s+')
HEADING = re.compile(r'^(#{1,6})\s+(.*)$')
SRC_LINE = re.compile(r'^\s*(?:[-*>+]\s*)?(?:\*\*|__)?\s*\u0418\u0441\u0442\u043e\u0447\u043d\u0438(?:\u043a|\u043a\u0438|\u043a\u043e\u0432)\s*(?:\*\*|__)?\s*[:\uff1a]')
SRC_INLINE = re.compile(r'\u0418\u0441\u0442\u043e\u0447\u043d\u0438(?:\u043a|\u043a\u0438|\u043a\u043e\u0432)(?:\*\*|__)?\s*[:\uff1a]')
SRC_HEADING = re.compile(r'^\u0418\u0441\u0442\u043e\u0447\u043d\u0438')


def parse_args():
    ap = argparse.ArgumentParser(description="Сверка чисел спеков с кодом (index.json) и данными")
    ap.add_argument("--spec", required=True, help="папка со спеками (.md), только чтение")
    ap.add_argument("--index", required=True, help="index.json от codeindex")
    ap.add_argument("--data", required=True, help="папка с данными (JSON/CSV)")
    ap.add_argument("--out-dir", default="verify-out", help="куда писать verify-auto.md/.json")
    ap.add_argument("--out-md", help="полный путь markdown-отчёта (перекрывает --out-dir)")
    ap.add_argument("--out-json", help="полный путь JSON-отчёта (перекрывает --out-dir)")
    ap.add_argument("--tol", type=float, default=1e-4, help="абсолютный допуск сравнения (1e-4)")
    ap.add_argument("--factors", default="2,10,60,100,120,1000", help="множители для производных форм ×N / ÷N")
    ap.add_argument("--no-derived", action="store_true", help="только точные совпадения")
    ap.add_argument("--no-pairs", action="store_true", help="не искать произведения/частные пар литералов")
    ap.add_argument("--entity-exclude", default="dialog,speakers,tilemaps,tilesets,fonts,ui,export",
                    help="подпапки/префиксы data, не сканируемые как сущности")
    ap.add_argument("--max-notfound", type=int, default=60, help="сколько NOT_FOUND на файл в markdown")
    ap.add_argument("--top", type=int, default=20, help="размер общего топа NOT_FOUND")
    ap.add_argument("--dump-claims", action="store_true", help="класть в JSON все утверждения, не только NOT_FOUND")
    ap.add_argument("--include", help="маска файлов спеки (fnmatch), напр. '0[1-4]*.md'")
    return ap.parse_args()


# ----------------------------------------------------------------------------
# области поиска значений
# ----------------------------------------------------------------------------
class Scope:
    __slots__ = ("label", "kind", "vals", "n", "small")

    def __init__(self, label, kind, values):
        self.label = label
        self.kind = kind          # method | type | file | data-file | data-entity
        self.vals = sorted(set(values))
        self.n = len(self.vals)
        self.small = [v for v in self.vals if v not in (0.0, 1.0, -1.0)]

    def has(self, v, tol):
        i = bisect.bisect_left(self.vals, v - tol)
        return i < self.n and self.vals[i] <= v + tol

    def pair(self, v, tol):
        """v == a*b  или  v == a/b  для литералов a, b области (малые области)."""
        s = self.small
        if len(s) > 260 or not s:
            return None
        for a in s:
            for target, how in ((v / a, "*"), (v * a, "/")):
                if self.has(target, tol / max(abs(a), 1.0) if how == "*" else tol * max(abs(a), 1.0)) and target not in (0.0, 1.0, -1.0):
                    return f"{a:g} {how} {target:g}"
        return None


class CodeIndex:
    def __init__(self, path):
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
        self.meta = d["meta"]
        self.lits = []           # (value, file, owner_type, owner, line)
        self.by_type = defaultdict(list)
        self.by_member = defaultdict(list)
        self.by_file = defaultdict(list)
        self.type_ids = set()
        self.types_by_name = defaultdict(set)
        self.files_by_base = defaultdict(set)
        for t in d["types"]:
            self.type_ids.add(t["id"])
            self.types_by_name[t["name"]].add(t["id"])
        for l in d["literals"]:
            if l["kind"] != "num":
                continue
            try:
                v = float(l["value"])
            except ValueError:
                continue
            i = len(self.lits)
            self.lits.append((v, l["file"], l["owner_type"], l["owner"], l["line"]))
            self.by_type[l["owner_type"]].append(i)
            self.by_member[(l["owner_type"], l["owner"])].append(i)
            self.by_file[l["file"]].append(i)
        for f in self.by_file:
            self.files_by_base[os.path.basename(f).lower()].add(f)
        for t in d["types"]:
            self.files_by_base[os.path.basename(t["file"]).lower()].add(t["file"])
        self.sorted_ids = sorted(self.type_ids)
        self.global_vals = sorted((l[0], k) for k, l in enumerate(self.lits))
        self.gv = [x[0] for x in self.global_vals]

    def files_matching(self, pat):
        pat = pat.lower()
        if "*" in pat or "?" in pat:
            return sorted({f for b, fs in self.files_by_base.items() if fnmatch.fnmatch(b, pat) for f in fs})
        return sorted(self.files_by_base.get(pat, ()))

    def type_family(self, tid):
        """tid + все вложенные типы."""
        out = [tid]
        i = bisect.bisect_left(self.sorted_ids, tid + ".")
        while i < len(self.sorted_ids) and self.sorted_ids[i].startswith(tid + "."):
            out.append(self.sorted_ids[i])
            i += 1
        return out

    def scope_from(self, idxs, label, kind):
        return Scope(label, kind, [self.lits[i][0] for i in idxs])

    def types_named(self, name, files=None):
        ids = set()
        for tid in self.types_by_name.get(name.split(".")[-1], ()):
            if tid == name or tid.endswith("." + name) or "." not in name:
                ids.add(tid)
        if files is not None:
            fset = set(files)
            filt = {t for t in ids if any(self.lits[i][1] in fset for i in self.by_type.get(t, [])[:1]) or self._type_in_files(t, fset)}
            if filt:
                return filt
        return ids

    def _type_in_files(self, tid, fset):
        for i in self.by_type.get(tid, ()):
            if self.lits[i][1] in fset:
                return True
        return False

    def member_scopes(self, name, files):
        """name = 'Method' | 'Type' | 'Type.Member'. Возвращает (scopes, found_in_files)."""
        fset = set(files) if files else None
        res = []
        parts = name.split(".")
        if len(parts) >= 2:
            tname, mname = ".".join(parts[:-1]), parts[-1]
            idxs = []
            for tid in self.types_named(tname, files):
                for (ot, ow), lst in self.by_member.items() if False else []:
                    pass
            for tid in self.types_named(tname, None):
                for fam in self.type_family(tid):
                    for (ot, ow) in [(fam, mname)]:
                        idxs += self.by_member.get((ot, ow), [])
                    idxs += self.by_member.get((fam, mname + ".get"), []) + self.by_member.get((fam, mname + ".set"), [])
            if idxs:
                res.append(self.scope_from(idxs, name, "method"))
            # Type.NestedType
            for tid in self.types_named(parts[-1], None):
                if tid.endswith("." + name) or tid == name:
                    idxs2 = [i for fam in self.type_family(tid) for i in self.by_type.get(fam, [])]
                    if idxs2:
                        res.append(self.scope_from(idxs2, name, "type"))
            return res
        # простое имя: тип(ы)
        tids = self.types_named(name, files)
        idxs = [i for tid in tids for fam in self.type_family(tid) for i in self.by_type.get(fam, [])]
        if idxs:
            res.append(self.scope_from(idxs, name, "type"))
        # метод/поле с таким именем (в файлах, иначе везде)
        idxm = []
        for (ot, ow), lst in self.member_index().get(name, {}).items():
            for i in lst:
                if fset is None or self.lits[i][1] in fset:
                    idxm.append(i)
        if not idxm and fset is not None:
            for (ot, ow), lst in self.member_index().get(name, {}).items():
                idxm += lst
        if idxm:
            res.append(self.scope_from(idxm, name, "method"))
        return res

    _midx = None

    def member_index(self):
        if self._midx is None:
            m = defaultdict(dict)
            for (ot, ow), lst in self.by_member.items():
                base = ow.split(".")[0]
                m[base][(ot, ow)] = lst
            self._midx = m
        return self._midx

    def where(self, v, tol, prefer_files=(), limit=3):
        lo = bisect.bisect_left(self.gv, v - tol)
        hits = []
        while lo < len(self.gv) and self.gv[lo] <= v + tol:
            hits.append(self.global_vals[lo][1])
            lo += 1
            if len(hits) > 200:
                break
        pf = set(prefer_files)
        hits.sort(key=lambda i: (self.lits[i][1] not in pf, self.lits[i][1], self.lits[i][4]))
        out = []
        for i in hits[:limit]:
            _, f, ot, ow, ln = self.lits[i]
            out.append(f"{f}:{ln} {ot or ''}.{ow}")
        return out, len(hits)


